window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"module":"yiliao","prompt":"氯吡格雷的作用机制是？","options":["溶解纤维蛋白","抑制环氧化酶","增强抗凝血酶Ⅲ","阻断血小板ADP受体（P2Y12）"],"answer":3,"explanation":"氯吡格雷选择性阻断血小板ADP受体，抑制血小板聚集，用于动脉血栓防治。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1501","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"右旋糖酐禁用于？","options":["低血容量休克","严重血小板减少和出血性疾病","血液高凝状态","术后血栓预防"],"answer":1,"explanation":"右旋糖酐抑制血小板功能，出血性疾病患者禁用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1502","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"叶酸拮抗药甲氨蝶呤中毒的解救药是？","options":["维生素B12","亚叶酸钙","维生素C","维生素K"],"answer":1,"explanation":"亚叶酸钙（甲酰四氢叶酸钙）提供四氢叶酸，解救甲氨蝶呤对叶酸代谢的阻断。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1503","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"治疗缺铁性贫血铁剂疗效最早的指标是？","options":["血清铁正常","血红蛋白升高","红细胞计数正常","网织红细胞计数升高"],"answer":3,"explanation":"服铁剂后3-4天网织红细胞开始升高，是疗效出现最早的指标。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1504","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"铁剂治疗缺铁性贫血，血红蛋白正常后仍需继续服药的原因是？","options":["促进白细胞生成","防止药物依赖","补足体内储存铁","预防感染"],"answer":2,"explanation":"血红蛋白恢复正常后仍需继续服药2-3个月，补足储存铁防止复发。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1505","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"再生障碍性贫血的治疗不包括？","options":["雄激素","铁剂","免疫抑制剂","造血干细胞移植"],"answer":1,"explanation":"再障是造血干细胞损伤，不是缺铁，铁剂无效。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1506","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"维生素K参与合成的凝血因子是？","options":["Ⅱ、Ⅶ、Ⅸ、Ⅹ","Ⅰ、Ⅲ、Ⅴ、Ⅻ","Ⅴ、Ⅷ、Ⅺ、Ⅻ","Ⅰ、Ⅱ、Ⅴ、Ⅷ"],"answer":0,"explanation":"维生素K依赖性凝血因子为Ⅱ、Ⅶ、Ⅸ、Ⅹ。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1507","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝素抗凝作用最强的给药途径是？","options":["口服","肌内注射","皮下注射","静脉给药"],"answer":3,"explanation":"肝素口服不吸收，静注立即起效，抗凝作用最强。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1508","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"双香豆素类药物与苯巴比妥合用后？","options":["抗凝作用减弱","抗凝作用增强","无相互影响","出血风险增大"],"answer":0,"explanation":"苯巴比妥为肝药酶诱导剂，加速华法林代谢，抗凝作用减弱。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1509","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"奥美拉唑长期应用需注意？","options":["必然导致胃癌","可能引起维生素B12吸收减少","永久性胃酸缺乏","骨质疏松不可避免"],"answer":1,"explanation":"长期抑酸可影响维生素B12吸收和钙吸收，需注意监测，非必然发生。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1510","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"多潘立酮（吗丁啉）的作用是？","options":["促进胃动力（外周多巴胺受体阻断）","抑制胃酸","保护胃黏膜","止泻"],"answer":0,"explanation":"多潘立酮阻断外周多巴胺受体，促进胃排空，用于功能性消化不良。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1511","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乳酶生的作用是？","options":["杀灭肠道细菌","补充肠道正常菌群（活乳酸杆菌制剂）","中和胃酸","止吐"],"answer":1,"explanation":"乳酶生为活乳酸杆菌制剂，抑制腐败菌繁殖、促进消化，不宜与抗菌药同服。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1512","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"微生态制剂（双歧杆菌制剂）不宜与什么同服？","options":["钙剂","维生素","抗菌药物","胃黏膜保护剂"],"answer":2,"explanation":"抗菌药物可杀灭活菌制剂，应间隔服用。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1513","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硫酸镁口服的作用是？","options":["抗惊厥","镇静","导泻","降压"],"answer":2,"explanation":"口服硫酸镁不被吸收，形成高渗刺激肠蠕动而导泻；注射才有镇静降压作用。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1514","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硫酸镁注射给药的作用是？","options":["导泻","抗惊厥、降血压","利胆","通便"],"answer":1,"explanation":"注射硫酸镁抑制中枢和神经肌肉传导，用于子痫、惊厥和高血压危象。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1515","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"开塞露的主要成分是？","options":["乳果糖","硫酸镁","酚酞","甘油（山梨醇）"],"answer":3,"explanation":"开塞露为甘油制剂，润滑并刺激肠壁，用于便秘临时通便。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1516","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"酚酞属于？","options":["止泻药","润滑性泻药","容积性泻药","刺激性泻药"],"answer":3,"explanation":"酚酞刺激结肠黏膜促进蠕动，属刺激性泻药，长期使用可致依赖。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1517","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"蒙脱石散止泻的机制是？","options":["中和胃酸","抑制肠蠕动","杀灭细菌","覆盖消化道黏膜，吸附病原体和毒素"],"answer":3,"explanation":"蒙脱石散天然硅酸盐制剂，覆盖保护黏膜并吸附病原，不抑制肠蠕动。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1518","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"地芬诺酯止泻的机制是？","options":["吸附毒素","抑制肠道平滑肌蠕动（类似阿片作用）","调节菌群","保护黏膜"],"answer":1,"explanation":"地芬诺酯为哌替啶衍生物，直接作用于肠道阿片受体，减少肠蠕动。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1519","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"昂丹司琼止吐的机制是？","options":["阻断多巴胺受体","阻断5-HT3受体","阻断组胺受体","抑制呕吐中枢代谢"],"answer":1,"explanation":"昂丹司琼为5-HT3受体阻断药，用于化疗、放疗所致呕吐，效果好。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1520","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯丙嗪止吐的特点是？","options":["对晕动病（晕车）所致呕吐无效","对所有呕吐均有效","只对晕动病有效","促进胃排空"],"answer":0,"explanation":"氯丙嗪抑制催吐化学感受区，对药物、妊娠等呕吐有效，对前庭刺激所致晕动病无效。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1521","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"组胺的生理作用不包括？","options":["扩张血管","增加毛细血管通透性","收缩支气管平滑肌","收缩瞳孔"],"answer":0,"explanation":"组胺扩张血管、增通透性、收缩支气管和胃肠平滑肌，不收缩瞳孔。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1522","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"H1受体阻断药最常见的中枢作用是？","options":["镇静催眠","兴奋躁动","呼吸抑制","惊厥"],"answer":0,"explanation":"第一代H1阻断药（苯海拉明、异丙嗪）有中枢镇静作用，第二代（氯雷他定）中枢作用弱。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1523","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氯雷他定与苯海拉明比较，优点是？","options":["中枢镇静作用弱","抗过敏作用更强","起效更慢","半衰期更短"],"answer":0,"explanation":"氯雷他定为第二代H1阻断药，不易透过血脑屏障，中枢镇静作用弱。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1524","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"钙剂抗过敏的机制是？","options":["阻断组胺受体","降低毛细血管通透性","抑制组胺合成","稳定溶酶体膜"],"answer":1,"explanation":"钙剂降低毛细血管通透性、减少渗出，辅助治疗过敏性疾病。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1525","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"色甘酸钠的给药途径是？","options":["肌内注射","口服","吸入给药","静脉注射"],"answer":2,"explanation":"色甘酸钠口服吸收差，采用吸入（粉雾）给药预防哮喘发作。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1526","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"氨茶碱治疗心源性哮喘的机制不包括？","options":["利尿","扩张支气管","增强心肌收缩力","扩张血管"],"answer":2,"explanation":"氨茶碱有强心、利尿、扩张血管和支气管作用，不直接增强心肌收缩力（其强心作用与抑制磷酸二酯酶有关，但机制描述以正性肌力为辅）。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1527","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"特布他林属于？","options":["β2受体激动药","β1受体激动药","α受体激动药","M受体激动药"],"answer":0,"explanation":"特布他林为选择性β2受体激动剂，用于支气管哮喘。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1528","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"异丙托溴铵平喘的机制是？","options":["抑制磷酸二酯酶","激动β2受体","阻断支气管M受体","抗炎"],"answer":2,"explanation":"异丙托溴铵为阿托品衍生物，阻断M受体舒张支气管，适用于不能耐受β2激动剂者。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1529","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"布地奈德属于？","options":["白三烯调节剂","β2受体激动药","吸入性糖皮质激素","茶碱类"],"answer":2,"explanation":"布地奈德为局部吸入用糖皮质激素，是哮喘长期控制的首选抗炎药。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1530","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"白三烯调节剂（孟鲁司特）的作用是？","options":["中和过敏原","扩张支气管立即起效","阻断白三烯受体，用于哮喘预防","抑制咳嗽反射"],"answer":2,"explanation":"孟鲁司特阻断白三烯受体，减轻气道炎症，用于哮喘预防和阿司匹林哮喘。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1531","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"酮替芬的作用是？","options":["兼有抗组胺和稳定肥大细胞膜作用","单纯扩张支气管","糖皮质激素作用","镇咳"],"answer":0,"explanation":"酮替芬为H1阻断药兼抑制肥大细胞释放介质，用于预防哮喘和过敏性鼻炎。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1532","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"哮喘持续状态不宜使用的药物是？","options":["沙丁胺醇","糖皮质激素","氨茶碱","吗啡"],"answer":3,"explanation":"吗啡抑制呼吸中枢并释放组胺收缩支气管，哮喘患者禁用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1533","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"治疗过敏性休克除肾上腺素外还可辅用？","options":["去甲肾上腺素","糖皮质激素","阿托品","毛果芸香碱"],"answer":1,"explanation":"糖皮质激素抗过敏抗休克，作为过敏性休克的辅助治疗药物。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1534","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素过敏性休克最主要的死亡原因是？","options":["肾衰竭","心律失常","喉头水肿和支气管痉挛致窒息","脑出血"],"answer":2,"explanation":"青霉素过敏性休克死于喉头水肿、支气管痉挛（窒息）和循环衰竭。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1535","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风抗毒素（TAT）皮试阳性的正确处理是？","options":["加大剂量注射","直接注射","改用青霉素","采用脱敏注射或用人破伤风免疫球蛋白"],"answer":3,"explanation":"TAT皮试阳性者采用脱敏注射（分次增量）或改用人破伤风免疫球蛋白。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1536","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风抗毒素属于？","options":["疫苗","类毒素","抗生素","特异性抗体（被动免疫制剂）"],"answer":3,"explanation":"TAT是马血清制备的特异性抗体，属被动免疫，可引起过敏反应。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1537","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风类毒素属于？","options":["抗生素","被动免疫制剂","主动免疫制剂（疫苗）","抗毒素"],"answer":2,"explanation":"类毒素刺激机体产生抗体，属主动免疫，用于预防接种。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1538","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"干扰素的主要作用不包括？","options":["抗肿瘤","抗病毒","直接杀灭细菌","免疫调节"],"answer":2,"explanation":"干扰素抗病毒、抗肿瘤、免疫调节，对细菌无直接杀灭作用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1539","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿昔洛韦的作用机制是？","options":["阻断病毒吸附","抑制病毒RNA聚合酶","抑制病毒DNA聚合酶","抑制病毒蛋白质合成"],"answer":2,"explanation":"阿昔洛韦在感染细胞内转变为三磷酸形式，抑制病毒DNA聚合酶，对疱疹病毒有效。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1540","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"革兰阳性菌与革兰阴性菌细胞壁的主要区别成分是？","options":["磷壁酸（阳性菌特有）","外膜（阴性菌特有）","脂多糖","肽聚糖"],"answer":0,"explanation":"革兰阳性菌细胞壁含大量磷壁酸，革兰阴性菌有外膜和脂多糖，两者共有肽聚糖。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1541","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"革兰阴性菌的内毒素成分是？","options":["外毒素","脂多糖（LPS）","磷壁酸","荚膜"],"answer":1,"explanation":"革兰阴性菌内毒素即细胞壁外膜的脂多糖，菌体裂解后释放。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1542","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"内毒素的特点是？","options":["可经甲醛脱毒制成类毒素","不耐热、毒性强","耐热、毒性较弱、不能制成类毒素","对组织有选择性毒性作用"],"answer":2,"explanation":"内毒素耐热、毒性较外毒素弱、无组织选择性，甲醛处理不能脱毒制成类毒素。","exam":"医疗编","__sub":"微生物与免疫","diff":3,"id":"yl-1543","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"外毒素的特点是？","options":["由革兰阴性菌裂解产生","耐热性强","毒性强、有组织选择性、可制成类毒素","不能制成类毒素"],"answer":2,"explanation":"外毒素多为革兰阳性菌分泌的蛋白质，毒性强且有组织选择性，甲醛脱毒后可制成类毒素（疫苗）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1544","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌芽孢的特点是？","options":["只存在于革兰阴性菌","是细菌的繁殖方式","对热和干燥抵抗力强","与细菌致病力直接相关"],"answer":2,"explanation":"芽孢是细菌的休眠体，耐热性强，是灭菌效果的评价指标（杀灭芽孢为灭菌标准）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1545","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"杀灭细菌芽孢的方法是？","options":["低温冷藏","紫外线照射","75%酒精浸泡","高压蒸汽灭菌法"],"answer":3,"explanation":"高压蒸汽灭菌（121℃、20分钟）可杀灭芽孢，是效果最可靠的灭菌法。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1546","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌荚膜的功能是？","options":["抗吞噬作用","细菌运动","细菌繁殖","产生毒素"],"answer":0,"explanation":"荚膜有抗吞噬、抗干燥等作用，与细菌侵袭力有关。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1547","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌鞭毛的功能是？","options":["黏附","抗吞噬","抵抗干燥","运动"],"answer":3,"explanation":"鞭毛是细菌的运动器官，有鞭毛的细菌可运动。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1548","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌菌毛的功能是？","options":["抗吞噬","运动","黏附（普通菌毛）与遗传物质传递（性菌毛）","产生毒素"],"answer":2,"explanation":"普通菌毛介导细菌对黏膜的黏附（与致病有关），性菌毛传递质粒。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1549","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌的遗传物质包括？","options":["染色体和质粒","只有染色体","只有质粒","核糖体"],"answer":0,"explanation":"细菌基因组包括染色体DNA和质粒（染色体外遗传物质，与耐药性传递有关）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1550","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"质粒的功能是？","options":["细菌染色","细菌运动","细菌呼吸","携带耐药基因等染色体外遗传信息"],"answer":3,"explanation":"质粒是细菌染色体外环状DNA，可携带耐药基因、毒力基因并经性菌毛传递。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1551","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"紫外线杀菌的机制是？","options":["破坏细胞膜","破坏细胞壁","干扰细菌DNA复制","抑制蛋白质合成"],"answer":2,"explanation":"紫外线使DNA同链相邻嘧啶形成二聚体，干扰复制，用于空气和物体表面消毒。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1552","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高压蒸汽灭菌的条件是？","options":["100℃、10分钟","121℃、15-30分钟","80℃、30分钟","60℃、1小时"],"answer":1,"explanation":"121℃维持15-30分钟可杀灭包括芽孢在内的一切微生物。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1553","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"巴氏消毒法用于？","options":["牛奶和酒类消毒","手术器械灭菌","空气消毒","皮肤消毒"],"answer":0,"explanation":"巴氏消毒（61-62℃30分钟或71.7℃15-30秒）用于牛奶、酒类等不耐高温物品消毒。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1554","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"75%乙醇的杀菌机制是？","options":["使菌体蛋白质变性凝固","氧化细菌酶类","破坏细胞壁","抑制DNA复制"],"answer":0,"explanation":"乙醇使蛋白质变性凝固，浓度过高（95%）反而因表面蛋白凝固形成保护膜而杀菌力下降。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1555","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常菌群的作用不包括？","options":["引起自身免疫病","生物拮抗","营养作用","免疫促进"],"answer":0,"explanation":"正常菌群有生物拮抗、营养（合成维生素）、免疫促进等作用，不引起自身免疫病。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1556","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"条件致病菌致病的条件不包括？","options":["细菌毒力显著增强（外源性强毒株）","机体免疫功能低下","菌群失调","定位转移"],"answer":0,"explanation":"条件致病菌在免疫低下、菌群失调、寄居部位改变时致病；其本身毒力通常不强。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1557","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"医院感染最常见的病原体是？","options":["真菌","病毒","细菌（多为条件致病菌）","寄生虫"],"answer":2,"explanation":"医院感染以细菌为主，多为耐药的条件致病菌（如铜绿假单胞菌、金黄色葡萄球菌）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1558","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"金黄色葡萄球菌的致病物质不包括？","options":["血浆凝固酶","肠毒素","外毒素（多种）","内毒素"],"answer":2,"explanation":"金黄色葡萄球菌产生多种外毒素和酶（凝固酶等），不含内毒素（内毒素为革兰阴性菌所有）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1559","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"化脓性感染最常见的病原菌是？","options":["结核分枝杆菌","大肠埃希菌","金黄色葡萄球菌","霍乱弧菌"],"answer":2,"explanation":"金黄色葡萄球菌是化脓性感染最常见的病原菌，产生血浆凝固酶使感染局限化。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1560","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"链球菌感染后引起的超敏反应性疾病是？","options":["伤寒","风湿热和急性肾小球肾炎","破伤风","白喉"],"answer":1,"explanation":"A群链球菌感染后可发生风湿热、急性肾小球肾炎等Ⅲ型（或Ⅱ型）超敏反应性疾病。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1561","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗O试验（ASO）用于辅助诊断？","options":["梅毒","伤寒","结核病","风湿热"],"answer":3,"explanation":"ASO试验检测链球菌溶血素O的抗体，滴度升高提示链球菌感染，辅助诊断风湿热。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1562","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脑膜炎奈瑟菌的传播途径是？","options":["粪-口传播","呼吸道飞沫传播","血液传播","接触传播"],"answer":1,"explanation":"脑膜炎奈瑟菌经呼吸道飞沫传播，引起流行性脑脊髓膜炎（流脑）。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1563","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"伤寒的病原体是？","options":["大肠埃希菌","志贺菌","霍乱弧菌","伤寒沙门菌"],"answer":3,"explanation":"伤寒由伤寒沙门菌引起，经粪-口传播，典型表现为持续发热、相对缓脉、玫瑰疹。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1564","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"志贺菌引起？","options":["伤寒","细菌性痢疾","霍乱","食物中毒（沙门菌型）"],"answer":1,"explanation":"志贺菌（痢疾杆菌）引起细菌性痢疾，表现为发热、腹痛、腹泻、黏液脓血便、里急后重。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1565","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"霍乱弧菌的致病物质主要是？","options":["荚膜","内毒素","霍乱肠毒素","血浆凝固酶"],"answer":2,"explanation":"霍乱肠毒素激活腺苷酸环化酶，使肠液大量分泌，引起剧烈水样腹泻。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1566","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"霍乱的典型大便性状是？","options":["米泔水样便","黏液脓血便","柏油样便","果酱样便"],"answer":0,"explanation":"霍乱弧菌肠毒素致大量肠液分泌，排出米泔水样便，可致严重脱水。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1567","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核分枝杆菌的染色特点是？","options":["革兰染色阴性","革兰染色阳性","抗酸染色阳性","瑞氏染色阳性"],"answer":2,"explanation":"结核分枝杆菌细胞壁含大量脂质（分枝菌酸），抗酸染色呈红色阳性。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1568","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核分枝杆菌的致病物质主要是？","options":["菌体成分（脂质等）引发的Ⅳ型超敏反应","外毒素","内毒素","侵袭性酶"],"answer":0,"explanation":"结核杆菌不产生外毒素和内毒素，其致病与菌体脂质等成分引发的免疫病理（Ⅳ型超敏反应）有关。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1569","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核菌素试验（PPD）的原理是？","options":["Ⅳ型超敏反应（迟发型）","Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅲ型超敏反应"],"answer":0,"explanation":"PPD试验检测机体对结核杆菌的细胞免疫（Ⅳ型超敏反应），48-72小时观察结果。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1570","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风梭菌的感染条件是？","options":["呼吸道","浅表清洁伤口","深部厌氧伤口","消化道"],"answer":2,"explanation":"破伤风梭菌为厌氧菌，深部窄伤口（缺氧环境）易感染，产生痉挛毒素。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1571","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风痉挛毒素的作用是？","options":["阻断抑制性神经递质释放，引起骨骼肌强直性痉挛","破坏红细胞","损伤心肌","抑制呼吸中枢代谢"],"answer":0,"explanation":"痉挛毒素阻断脊髓抑制性中间神经元，使伸肌与屈肌同时强直收缩，出现牙关紧闭、角弓反张。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1572","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"产气荚膜梭菌引起？","options":["破伤风","气性坏疽","肉毒中毒","白喉"],"answer":1,"explanation":"产气荚膜梭菌产生多种毒素和酶，引起气性坏疽（组织气肿、坏死）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1573","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肉毒梭菌的致病物质是？","options":["侵袭性酶","内毒素","肠毒素","肉毒毒素（最强的神经外毒素）"],"answer":3,"explanation":"肉毒毒素是已知最强的神经毒素，阻断胆碱能神经末梢释放乙酰胆碱，引起肌肉弛缓性麻痹。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1574","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"白喉杆菌的致病物质是？","options":["白喉外毒素","内毒素","荚膜","芽孢"],"answer":0,"explanation":"白喉外毒素抑制细胞蛋白质合成，引起心肌和神经损害，局部形成假膜。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1575","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"白喉外毒素的作用机制是？","options":["抑制细胞蛋白质合成","破坏细胞膜","抑制DNA复制","激活腺苷酸环化酶"],"answer":0,"explanation":"白喉外毒素使延伸因子2失活，阻断细胞蛋白质合成，致心肌炎和周围神经麻痹。","exam":"医疗编","__sub":"微生物与免疫","diff":3,"id":"yl-1576","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"铜绿假单胞菌的特点是？","options":["对青霉素高度敏感","天然耐药性强，为医院感染重要病原菌","只引起肠道感染","不产生色素"],"answer":1,"explanation":"铜绿假单胞菌（绿脓杆菌）天然耐药性强，产生绿色色素，是烧伤、囊性纤维化等医院感染的重要病原菌。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1577","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"幽门螺杆菌与下列哪种疾病密切相关？","options":["慢性胃炎和消化性溃疡","溃疡性结肠炎","急性胰腺炎","病毒性肝炎"],"answer":0,"explanation":"幽门螺杆菌是慢性胃炎、消化性溃疡的重要致病因子，与胃癌发生相关。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1578","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"支原体的特点是？","options":["只能寄生于活细胞内","有细胞壁","对青霉素敏感","无细胞壁，对青霉素不敏感"],"answer":3,"explanation":"支原体无细胞壁（是最小的原核细胞型微生物），青霉素类（作用于细胞壁）无效，用大环内酯类。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1579","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"衣原体的特点是？","options":["无细胞壁","可在人工培养基生长","严格细胞内寄生，有独特发育周期","为病毒的一种"],"answer":2,"explanation":"衣原体严格细胞内寄生，有原体和网状体（始体）发育周期。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1580","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"立克次体的传播媒介是？","options":["飞沫","节肢动物（虱、蚤、蜱等）","水源","食物"],"answer":1,"explanation":"立克次体经虱、蚤、蜱、螨等节肢动物叮咬传播，引起斑疹伤寒等。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1581","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"螺旋体中引起梅毒的病原体是？","options":["梅毒螺旋体（苍白密螺旋体）","钩端螺旋体","回归热螺旋体","伯氏疏螺旋体"],"answer":0,"explanation":"梅毒由梅毒螺旋体引起，经性接触和垂直传播，青霉素为首选治疗。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1582","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"钩端螺旋体病的主要传染源是？","options":["患者","鼠类和猪","蚊虫","家禽"],"answer":1,"explanation":"钩体病为人畜共患病，鼠类和猪是主要传染源，经疫水接触传播。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1583","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒的基本结构是？","options":["细胞器和细胞核","细胞膜和细胞质","细胞壁和核糖体","核心（核酸）和衣壳（蛋白质）"],"answer":3,"explanation":"病毒为非细胞型微生物，由核酸核心和蛋白质衣壳组成，部分有包膜。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1584","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒的增殖方式是？","options":["孢子生殖","二分裂","以核酸为模板进行复制","出芽生殖"],"answer":2,"explanation":"病毒缺乏独立代谢系统，必须以自身核酸为模板、利用宿主细胞进行复制增殖。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1585","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"干扰素的抗病毒机制是？","options":["破坏病毒包膜","直接杀灭病毒","阻止病毒吸附","诱导细胞产生抗病毒蛋白，间接抑制病毒"],"answer":3,"explanation":"干扰素刺激细胞合成抗病毒蛋白（如蛋白激酶等），间接抑制病毒复制，不直接杀灭病毒。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1586","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒垂直传播是指？","options":["经飞沫传播","经胎盘或产道由母体传给胎儿","经血液制品传播","经粪-口传播"],"answer":1,"explanation":"垂直传播指病原体经胎盘、产道或哺乳由母亲传给子代，如风疹病毒、乙肝病毒、HIV。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1587","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝病毒的传播途径不包括？","options":["性接触传播","血液传播","母婴传播","呼吸道飞沫"],"answer":3,"explanation":"乙肝经血液、母婴和性接触传播，不经呼吸道飞沫传播。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1588","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝病毒感染确诊最有意义的血清学指标是？","options":["肝功能正常","抗-HBs阳性（单独）","抗-HBc IgG阳性（单独）","HBsAg阳性（伴HBeAg或HBV DNA）"],"answer":3,"explanation":"HBsAg阳性表示乙肝病毒感染；抗-HBs阳性为免疫保护标志（疫苗接种或康复）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1589","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝疫苗接种产生的保护性抗体是？","options":["抗-HBs","抗-HBc","抗-HBe","HBsAg"],"answer":0,"explanation":"接种乙肝疫苗后产生抗-HBs（表面抗体），是中和性保护抗体。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1590","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝病毒属于？","options":["RNA病毒","DNA病毒","逆转录病毒（RNA）","缺陷病毒"],"answer":1,"explanation":"HBV为嗜肝DNA病毒，含部分环状双链DNA。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1591","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"丙肝病毒的特点是？","options":["有高效疫苗","DNA病毒","不易慢性化","RNA病毒，易慢性化"],"answer":3,"explanation":"HCV为RNA病毒，感染易慢性化（约50-85%），目前尚无疫苗，现可治愈（直接抗病毒药物）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1592","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"艾滋病的病原体是？","options":["人类免疫缺陷病毒（HIV）","人类T细胞白血病病毒","EB病毒","巨细胞病毒"],"answer":0,"explanation":"HIV为逆转录RNA病毒，主要破坏CD4+T淋巴细胞。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1593","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"HIV主要侵犯的细胞是？","options":["血小板","B淋巴细胞","红细胞","CD4+T淋巴细胞"],"answer":3,"explanation":"HIV通过gp120与CD4分子结合，感染并破坏CD4+T细胞，致免疫功能缺陷。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1594","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"艾滋病的传播途径不包括？","options":["母婴传播","性接触","血液传播","日常生活接触（握手、共餐）"],"answer":3,"explanation":"HIV经性、血液、母婴三种途径传播，日常接触不传播。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1595","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"HIV感染确诊常用的检查是？","options":["初筛ELISA","蛋白印迹试验（确认试验）","血常规","CD4计数"],"answer":1,"explanation":"HIV感染先经ELISA初筛，阳性者用蛋白印迹（Western blot）确认。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1596","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"狂犬病毒的传染源主要是？","options":["患者","患病犬、猫等动物","蚊虫","鼠类"],"answer":1,"explanation":"狂犬病的主要传染源是病犬，其次为猫等，经咬伤传播，发病后病死率近100%。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1597","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"狂犬病伤口的正确处理是？","options":["简单包扎","立即用肥皂水反复冲洗并接种疫苗","热敷伤口","挤压伤口"],"answer":1,"explanation":"被犬咬伤后立即用肥皂水和流水交替冲洗15分钟以上，消毒，并按程序接种狂犬疫苗，必要时用免疫球蛋白。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1598","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流感病毒最易变异的结构是？","options":["核蛋白","血凝素（HA）和神经氨酸酶（NA）","基质蛋白","RNA聚合酶"],"answer":1,"explanation":"HA和NA为流感病毒表面抗原，易发生变异（抗原漂移和转变），是流感反复流行的原因。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1599","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流感病毒的传播途径是？","options":["呼吸道飞沫","粪-口","血液","虫媒"],"answer":0,"explanation":"流感经呼吸道飞沫传播，冬春季流行，甲型易引起大流行。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1600","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"麻疹的典型表现是？","options":["发热当天出疹","发热3-4天后出疹，口腔麻疹黏膜斑（柯氏斑）","无发热出疹","出血性皮疹"],"answer":1,"explanation":"麻疹发热3-4天出疹，出疹前口腔可见麻疹黏膜斑（早期诊断标志），疹间皮肤正常。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1601","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"风疹对孕妇的主要危害是？","options":["引起胎儿先天畸形（先天性风疹综合征）","孕妇重症肺炎","流产不可避免","产后出血"],"answer":0,"explanation":"孕妇妊娠早期感染风疹病毒可致胎儿先天性风疹综合征（先天性心脏病、白内障、耳聋等）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1602","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流行性乙型脑炎的传播媒介是？","options":["血液制品","飞沫","粪-口","蚊虫"],"answer":3,"explanation":"乙脑经蚊虫叮咬传播，夏秋季流行，多见于儿童。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1603","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"流行性出血热的病原体是？","options":["黄热病毒","登革病毒","埃博拉病毒","汉坦病毒"],"answer":3,"explanation":"汉坦病毒引起流行性出血热（肾综合征出血热），经鼠类排泄物传播。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1604","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"真菌的基本结构特点是？","options":["非细胞型","原核细胞型","真核细胞型微生物","无细胞结构"],"answer":2,"explanation":"真菌为真核细胞型微生物，有典型细胞核和细胞器，细胞壁不含肽聚糖。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1605","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"皮肤癣菌主要侵犯？","options":["血液","内脏器官","皮肤角质层、毛发和指（趾）甲","神经系统"],"answer":2,"explanation":"皮肤癣菌（毛癣菌等）嗜角质蛋白，引起头癣、体癣、手足癣、甲癣。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1606","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"白色念珠菌的特点是？","options":["条件致病性真菌，正常存在于口腔、肠道等","强致病性真菌","只存在于土壤","为细菌的一种"],"answer":0,"explanation":"白色念珠菌为人体正常菌群，免疫低下、菌群失调时致病（鹅口疮、阴道炎等）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1607","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"新型隐球菌感染易侵犯？","options":["心脏","中枢神经系统","关节","甲状腺"],"answer":1,"explanation":"新型隐球菌经呼吸道吸入，易侵犯中枢神经系统引起隐球菌脑膜炎，脑脊液墨汁染色可见荚膜。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1608","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗生素相关性伪膜性肠炎的病原体是？","options":["伤寒沙门菌","金黄色葡萄球菌","霍乱弧菌","艰难梭菌"],"answer":3,"explanation":"长期大量使用广谱抗生素致菌群失调，艰难梭菌过度繁殖引起伪膜性肠炎。","exam":"医疗编","__sub":"微生物与免疫","diff":3,"id":"yl-1609","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗原的基本特性是？","options":["免疫原性和反应原性","只有免疫原性","只有反应原性","只有毒性"],"answer":0,"explanation":"完全抗原既有免疫原性（刺激机体产生免疫应答）又有反应原性（与产物特异性结合）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1610","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"半抗原的特点是？","options":["只有毒性","既有免疫原性又有反应原性","无任何抗原性","只有反应原性而无免疫原性"],"answer":3,"explanation":"半抗原（如青霉素降解物）能与抗体结合但单独不能刺激免疫应答，与载体蛋白结合后成为完全抗原。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1611","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"抗体（免疫球蛋白）的产生细胞是？","options":["T淋巴细胞","浆细胞（效应B细胞）","巨噬细胞","NK细胞"],"answer":1,"explanation":"B细胞受抗原刺激分化为浆细胞，由浆细胞合成并分泌抗体。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1612","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"免疫球蛋白中分子量最大的是？","options":["IgE","IgG","IgA","IgM"],"answer":3,"explanation":"IgM为五聚体，分子量最大，是个体发育中最早合成的抗体，也是感染早期出现的抗体。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1613","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"能通过胎盘的免疫球蛋白是？","options":["IgE","IgM","IgA","IgG"],"answer":3,"explanation":"IgG是唯一能通过胎盘的抗体，赋予新生儿被动免疫保护。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1614","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"参与Ⅰ型超敏反应的抗体是？","options":["IgG","IgE","IgM","IgA"],"answer":1,"explanation":"IgE与肥大细胞、嗜碱性粒细胞结合，再次接触变应原时释放组胺等介质，引起Ⅰ型超敏反应。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1615","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅰ型超敏反应的特点是？","options":["以组织损伤为主","发生快、以功能性紊乱为主、无明显组织损伤","发生缓慢","由IgG介导"],"answer":1,"explanation":"Ⅰ型（速发型）超敏反应发生快，主要引起毛细血管扩张、通透性增加、平滑肌收缩等功能紊乱。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1616","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"青霉素过敏性休克属于？","options":["Ⅲ型超敏反应","Ⅱ型超敏反应","Ⅰ型超敏反应","Ⅳ型超敏反应"],"answer":2,"explanation":"青霉素过敏性休克由IgE介导，属Ⅰ型（速发型）超敏反应。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1617","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅱ型超敏反应的特点是？","options":["抗体（IgG、IgM）与细胞表面抗原结合，破坏靶细胞","由IgE介导","以肉芽肿形成为特征","发生最慢"],"answer":0,"explanation":"Ⅱ型（细胞毒型）超敏反应由IgG、IgM与靶细胞抗原结合，经补体或吞噬细胞破坏靶细胞（如输血反应）。","exam":"医疗编","__sub":"微生物与免疫","diff":3,"id":"yl-1618","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"新生儿溶血症属于？","options":["Ⅲ型超敏反应","Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅳ型超敏反应"],"answer":2,"explanation":"Rh或ABO血型不合的新生儿溶血症由母体抗体破坏胎儿红细胞，属Ⅱ型超敏反应。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1619","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅲ型超敏反应的典型代表是？","options":["免疫复合物型（如链球菌感染后肾小球肾炎）","过敏性休克","输血反应","接触性皮炎"],"answer":0,"explanation":"Ⅲ型超敏反应由可溶性免疫复合物沉积引起炎症（如风湿热、链球菌感染后肾炎）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1620","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅳ型超敏反应的特点是？","options":["发生最快","由抗体介导","由T细胞介导，发生缓慢（24-72小时）","由补体介导"],"answer":2,"explanation":"Ⅳ型（迟发型）超敏反应由致敏T细胞介导，如结核菌素试验、接触性皮炎、移植排斥。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1621","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核菌素试验阳性反应的机制是？","options":["Ⅲ型超敏反应","Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅳ型超敏反应"],"answer":3,"explanation":"PPD试验为典型的Ⅳ型（迟发型）超敏反应，48-72小时出现红肿硬结。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1622","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"免疫系统的功能不包括？","options":["产生消化酶","免疫防御","免疫自稳","免疫监视"],"answer":0,"explanation":"免疫系统有防御（抗感染）、自稳（清除衰老细胞）、监视（清除突变细胞）三大功能。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1623","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中枢免疫器官包括？","options":["肝脏和脾脏","脾脏和淋巴结","扁桃体和阑尾","骨髓和胸腺"],"answer":3,"explanation":"中枢免疫器官（骨髓、胸腺）是免疫细胞发生、分化成熟的场所；外周免疫器官（脾、淋巴结等）是免疫应答场所。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1624","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"T淋巴细胞成熟的场所是？","options":["胸腺","骨髓","脾脏","淋巴结"],"answer":0,"explanation":"T细胞在胸腺内发育成熟；B细胞在骨髓（哺乳类）成熟。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1625","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"B淋巴细胞的功能主要是？","options":["产生抗体介导体液免疫","直接杀伤靶细胞","吞噬病原体","释放淋巴因子介导细胞免疫"],"answer":0,"explanation":"B细胞受抗原刺激增殖分化为浆细胞，产生抗体，介导体液免疫。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1626","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"NK细胞的特点是？","options":["产生抗体","需抗体协助才能活化","只杀伤病毒","无需抗原预先致敏即可杀伤靶细胞"],"answer":3,"explanation":"NK细胞（自然杀伤细胞）无需预先致敏、无MHC限制性，直接杀伤肿瘤细胞和病毒感染细胞。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1627","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"补体的生物学作用不包括？","options":["调理吞噬","溶解细胞","直接产生抗体","炎症介质作用"],"answer":2,"explanation":"补体经激活后可溶解细胞、调理吞噬、引起炎症、免疫黏附等，不产生抗体。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1628","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"经典途径激活补体的主要物质是？","options":["细菌脂多糖","抗原抗体复合物（IgG、IgM）","凝集素","备解素"],"answer":1,"explanation":"经典途径由抗原抗体复合物（IgG1-3、IgM）启动；脂多糖激活旁路途径。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1629","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"疫苗的基本原理是？","options":["补充免疫细胞","直接提供抗体","杀灭病原体","用抗原刺激机体产生特异性免疫（主动免疫）"],"answer":3,"explanation":"疫苗（抗原）接种后刺激机体主动产生抗体和细胞免疫，获得特异性免疫保护。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1630","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"人工主动免疫与人工被动免疫的主要区别是？","options":["前者生效快","前者接种抗原、产生慢而持久；后者注射抗体、生效快而短暂","后者持久","无区别"],"answer":1,"explanation":"人工主动免疫（疫苗）起效慢、维持久；人工被动免疫（免疫球蛋白、抗毒素）起效快、维持短。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1631","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"乙肝免疫球蛋白属于？","options":["抗生素","人工主动免疫制剂","类毒素","人工被动免疫制剂"],"answer":3,"explanation":"乙肝免疫球蛋白是含高效价抗-HBs的血浆制品，属被动免疫，用于暴露后应急保护。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1632","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"卡介苗（BCG）属于？","options":["灭活疫苗","减毒活疫苗","类毒素","抗毒素"],"answer":1,"explanation":"卡介苗为牛型结核杆菌减毒活疫苗，用于预防结核病。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1633","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风抗毒素（TAT）的作用机制是？","options":["中和游离的外毒素","杀灭破伤风杆菌","抑制细菌繁殖","溶解细菌细胞壁"],"answer":0,"explanation":"TAT为被动免疫制剂，中和游离外毒素，对已与神经组织结合的毒素无效。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-1634","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"免疫耐受是指？","options":["免疫功能低下","对特定抗原的特异性无应答状态","对所有抗原无应答","过敏反应"],"answer":1,"explanation":"免疫耐受是免疫系统对特定抗原不产生应答，具有抗原特异性，对自身抗原耐受是防止自身免疫病的关键。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1635","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"自身免疫病的发病机制主要是？","options":["补体过多","外源性抗原过多","免疫缺陷","对自身抗原的免疫耐受被打破"],"answer":3,"explanation":"自身免疫病是机体对自身组织产生免疫应答（耐受破坏），如系统性红斑狼疮、类风湿关节炎。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1636","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"超急性排斥反应的机制是？","options":["免疫缺陷","T细胞介导的迟发反应","免疫耐受","受者体内预存抗体与移植器官抗原结合（Ⅱ型超敏反应样）"],"answer":3,"explanation":"超急性排斥在移植后数分钟至数小时发生，由受者预存抗体（如抗血型抗体）引起。","exam":"医疗编","__sub":"微生物与免疫","diff":3,"id":"yl-1637","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"器官移植时最重要的组织配型抗原是？","options":["补体","血型抗原","人类白细胞抗原（HLA）","免疫球蛋白"],"answer":2,"explanation":"HLA（MHC）配型是器官移植成功的关键，HLA差异越大排斥反应越强。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1638","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肿瘤免疫逃逸的机制不包括？","options":["肿瘤细胞高表达MHC分子","肿瘤抗原表达下调","分泌免疫抑制因子","诱导免疫耐受"],"answer":0,"explanation":"肿瘤细胞常下调MHC表达以逃避免疫识别，而非高表达。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1639","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"免疫缺陷病的特点是？","options":["只表现为过敏","反复感染、易发生恶性肿瘤","只表现为自身免疫","无感染倾向"],"answer":1,"explanation":"免疫缺陷（如HIV、原发性免疫缺陷）表现为反复感染、易肿瘤、可伴自身免疫。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-1640","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人腋测法体温参考范围是？","options":["35.0-36.0℃","36.0-37.0℃","37.0-38.0℃","36.5-37.7℃"],"answer":1,"explanation":"腋测法正常为36.0-37.0℃；口测法36.3-37.2℃；肛测法36.5-37.7℃。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1641","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"发热最常见的病因是？","options":["内分泌代谢障碍","无菌性坏死物质吸收","抗原抗体反应","感染性发热"],"answer":3,"explanation":"感染性发热最常见，由各种病原体感染引起。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1642","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"弛张热的特点是？","options":["体温骤升骤降、高热期与无热期交替","体温恒定维持在39-40℃以上","体温常在39℃以上，24小时波动范围超过2℃","体温逐渐上升又逐渐下降"],"answer":2,"explanation":"弛张热常见于败血症、风湿热、重症肺结核等；稽留热24小时波动不超过1℃。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1643","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"间歇热的特点是？","options":["高热期与无热期交替出现","体温恒定","体温渐升渐降","低热持续"],"answer":0,"explanation":"间歇热见于疟疾、急性肾盂肾炎等，高热与无热反复交替。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1644","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"体温骤升骤降、高热与无热期交替出现，见于？","options":["结核病（长期低热）","大叶性肺炎（稽留热）","疟疾","伤寒（阶梯上升）"],"answer":2,"explanation":"疟疾发作时寒战高热、大汗后退热，呈间歇热。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1645","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"稽留热常见于？","options":["大叶性肺炎","疟疾","败血症","风湿热"],"answer":0,"explanation":"稽留热体温恒定于39-40℃以上，24小时波动<1℃，见于大叶性肺炎、伤寒高热期。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1646","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心源性水肿首先出现的部位是？","options":["身体下垂部位（下肢）","眼睑和面部","腹部","胸腔"],"answer":0,"explanation":"心源性水肿从下垂部位开始（仰卧者先骶部）；肾性水肿先从眼睑、面部开始。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1647","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肾性水肿的特点是？","options":["腹水为主","下肢下垂部位先肿","晨起眼睑和颜面水肿","非凹陷性水肿"],"answer":2,"explanation":"肾性水肿组织疏松部位先肿，晨起眼睑颜面水肿明显。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1648","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"干性咳嗽（无痰）常见于？","options":["肺脓肿","慢性支气管炎","支气管扩张","急性咽喉炎、胸膜炎"],"answer":3,"explanation":"干咳见于咽喉炎、胸膜炎、肺癌早期等；湿咳见于慢支、支扩、肺脓肿。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1649","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"咳痰呈铁锈色提示？","options":["肺炎链球菌肺炎","肺结核","肺脓肿","支气管扩张"],"answer":0,"explanation":"铁锈色痰是肺炎链球菌（肺炎球菌）肺炎的典型表现。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1650","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"咳大量脓臭痰提示？","options":["心源性哮喘","肺炎链球菌肺炎","干性胸膜炎","肺脓肿（厌氧菌感染）"],"answer":3,"explanation":"肺脓肿痰量大、静置分层，厌氧菌感染时痰有恶臭。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1651","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"痰液静置后分层（上层泡沫、中层浆液、下层脓块）见于？","options":["肺癌","大叶性肺炎","支气管扩张","哮喘"],"answer":2,"explanation":"支气管扩张和肺脓肿患者痰量多，静置后分三层。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1652","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"咯血与呕血的鉴别要点不包括？","options":["咯血前有恶心而呕血前有恶心（相同点）","咯血颜色鲜红、呕血暗红","咯血混有痰、呕血混有胃内容物","咯血pH碱性、呕血酸性"],"answer":0,"explanation":"咯血与呕血前均可有恶心，不是鉴别点；其余均为鉴别要点。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1653","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呼吸困难表现为吸气费力、三凹征，属于？","options":["呼气性呼吸困难","吸气性呼吸困难","混合性呼吸困难","心源性呼吸困难"],"answer":1,"explanation":"吸气性呼吸困难见于喉头水肿、气管异物等大气道梗阻，出现胸骨上窝、锁骨上窝、肋间隙凹陷（三凹征）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1654","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呼气性呼吸困难常见于？","options":["喉头水肿","支气管哮喘和阻塞性肺气肿","气管异物","大量胸腔积液"],"answer":1,"explanation":"呼气性呼吸困难因小气道狭窄、肺弹性减弱，呼气费力延长，见于哮喘、肺气肿。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1655","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Kussmaul呼吸（深大呼吸）常见于？","options":["支气管哮喘","糖尿病酮症酸中毒","脑出血","肺水肿"],"answer":1,"explanation":"代谢性酸中毒时呼吸深大（酸中毒大呼吸），代偿性排出CO2。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1656","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"潮式呼吸（Cheyne-Stokes呼吸）的特点是？","options":["呼吸深大规则","呼吸由浅慢逐渐深快再变浅慢，暂停后周而复始","呼吸浅快","呼吸突然停止"],"answer":1,"explanation":"潮式呼吸见于中枢神经系统疾病和心衰、尿毒症等，提示呼吸中枢兴奋性降低。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1657","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胸痛伴呼吸困难、气管向健侧移位，提示？","options":["大量气胸","心绞痛","肋间神经痛","肺结核"],"answer":0,"explanation":"大量气胸时患侧胸廓饱满、气管移向健侧，伴呼吸困难和胸痛。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1658","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心绞痛胸痛的特点是？","options":["深呼吸加重","刺痛持续数天","胸骨后压榨性疼痛，含服硝酸甘油可缓解","与体位有关"],"answer":2,"explanation":"典型心绞痛为胸骨后压榨性闷痛，持续3-5分钟，休息或含服硝酸甘油缓解。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1659","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胸痛伴吞咽困难提示？","options":["气胸","心绞痛","肋软骨炎","食管疾病"],"answer":3,"explanation":"食管疾病（食管炎、食管癌）胸痛常于吞咽时加重，伴吞咽困难。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1660","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"发绀的常见原因是？","options":["血液中碳氧血红蛋白增多（轻度）","血液中还原血红蛋白增多","贫血","白细胞增多"],"answer":1,"explanation":"发绀主要由还原血红蛋白增多（>50g/L）或异常血红蛋白血症引起。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1661","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中心性发绀的特点是？","options":["由局部血流障碍引起","仅肢端发绀、皮肤发凉","加温后消失","全身性发绀，皮肤温暖"],"answer":3,"explanation":"中心性发绀由心肺疾病致动脉血氧饱和度降低，全身分布、皮肤温暖；周围性发绀见于肢端、皮肤凉。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1662","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心悸的常见原因不包括？","options":["贫血","心律失常","甲状腺功能亢进","血糖升高"],"answer":3,"explanation":"心悸见于心律失常、心脏搏动增强（贫血、甲亢、发热）和神经症，与血糖无关。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1663","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"恶心呕吐伴头痛、喷射性呕吐提示？","options":["前庭功能障碍","幽门梗阻","急性胃肠炎","颅内压增高"],"answer":3,"explanation":"喷射性呕吐是颅内压增高的特征表现，呕吐前无恶心先兆。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1664","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呕血伴蜘蛛痣、肝掌，提示？","options":["肝硬化门脉高压","消化性溃疡","急性胃黏膜病变","食管癌"],"answer":0,"explanation":"肝硬化门脉高压致食管胃底静脉曲张破裂出血，伴肝病面容、蜘蛛痣、肝掌。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1665","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性腹泻伴里急后重提示？","options":["结肠肝曲病变","小肠病变","直肠病变（如细菌性痢疾）","胃部病变"],"answer":2,"explanation":"里急后重（便意频繁、排便不尽感）提示直肠刺激，见于菌痢、直肠癌等。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1666","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"溶血性黄疸的特点是？","options":["尿胆红素强阳性","结合胆红素升高为主","血清非结合胆红素升高，尿胆原增加、尿胆红素阴性","大便呈陶土色"],"answer":2,"explanation":"溶血性黄疸大量红细胞破坏，非结合胆红素升高，尿胆原增加而尿胆红素阴性。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1667","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胆汁淤积性黄疸的特点是？","options":["脾大伴溶血","尿胆原明显增加","非结合胆红素升高为主","大便呈陶土色、尿胆红素强阳性"],"answer":3,"explanation":"胆汁淤积（梗阻性）黄疸直接胆红素升高，尿胆红素强阳性、尿胆原减少，大便陶土色。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1668","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝细胞性黄疸的化验特点是？","options":["仅非结合胆红素升高","结合与非结合胆红素均升高，尿胆红素阳性、尿胆原增加","尿胆红素阴性","大便陶土色"],"answer":1,"explanation":"肝细胞性黄疸肝细胞摄取、结合、排泄胆红素均障碍，双相升高。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1669","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"意识障碍由轻到重的顺序是？","options":["昏迷→昏睡→嗜睡","嗜睡→意识模糊→昏睡→昏迷","意识模糊→嗜睡→昏睡","昏睡→意识模糊→昏迷"],"answer":1,"explanation":"意识障碍程度由轻到重：嗜睡、意识模糊、昏睡、昏迷（浅昏迷、深昏迷）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1670","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"浅昏迷与深昏迷的鉴别要点是？","options":["深昏迷对任何刺激均无反应、各种反射消失","浅昏迷无角膜反射","深昏迷仍有吞咽反射","浅昏迷瞳孔散大"],"answer":0,"explanation":"浅昏迷对强烈刺激尚有反应、反射存在；深昏迷对一切刺激无反应、深浅反射消失。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1671","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人安静状态下呼吸频率是？","options":["30-40次/分","8-12次/分","20-30次/分","12-20次/分"],"answer":3,"explanation":"正常成人呼吸12-20次/分，超过24次/分为呼吸过速。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1672","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人安静状态下心率为？","options":["100-120次/分","40-60次/分","60-100次/分","120-140次/分"],"answer":2,"explanation":"正常成人安静心率60-100次/分，>100为心动过速，<60为心动过缓。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1673","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人血压（收缩压/舒张压）为？","options":["80-120/50-80 mmHg","140-159/90-99 mmHg","90-139/60-89 mmHg","150-170/95-105 mmHg"],"answer":2,"explanation":"正常成人血压收缩压90-139mmHg、舒张压60-89mmHg；≥140/90为高血压。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1674","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脉压增大（>40mmHg）常见于？","options":["主动脉瓣关闭不全和甲状腺功能亢进","主动脉瓣狭窄","心包积液","休克"],"answer":0,"explanation":"脉压增大见于主动脉瓣关闭不全、甲亢、动脉硬化等；脉压减小见于心包积液、主动脉瓣狭窄。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1675","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"交替脉提示？","options":["主动脉瓣狭窄","右心衰竭","心包积液","左心衰竭"],"answer":3,"explanation":"交替脉（强弱交替）提示心肌严重损害，是左心衰竭的重要体征。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1676","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"奇脉（吸停脉）常见于？","options":["主动脉瓣关闭不全","左心衰竭","大量心包积液（心包填塞）","高血压"],"answer":2,"explanation":"奇脉指吸气时脉搏明显减弱或消失，见于心包填塞、哮喘重度发作。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1677","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"水冲脉常见于？","options":["主动脉瓣关闭不全","主动脉瓣狭窄","心包积液","二尖瓣狭窄"],"answer":0,"explanation":"水冲脉（脉搏骤起骤落）见于主动脉瓣关闭不全、甲亢、动脉导管未闭等。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1678","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人24小时尿量为？","options":["2000-3000 ml","500-1000 ml","1000-2000 ml","3000-4000 ml"],"answer":2,"explanation":"成人24小时尿量约1000-2000ml；<400ml为少尿，<100ml为无尿，>2500ml为多尿。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1679","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"24小时尿量少于400ml称为？","options":["正常","无尿","多尿","少尿"],"answer":3,"explanation":"少尿<400ml/24h，无尿<100ml/24h，多尿>2500ml/24h。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1680","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血尿伴疼痛（肾绞痛）提示？","options":["急性肾炎","泌尿系结石","泌尿系肿瘤","膀胱炎"],"answer":1,"explanation":"血尿伴剧烈腰痛（肾绞痛）多为结石梗阻；无痛性血尿警惕肿瘤。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1681","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"无痛性肉眼血尿应首先考虑？","options":["肾结核","泌尿系结石","急性膀胱炎","泌尿系肿瘤"],"answer":3,"explanation":"中老年人无痛性全程血尿首先警惕泌尿系肿瘤（如膀胱癌、肾癌）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1682","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"尿频、尿急、尿痛（膀胱刺激征）常见于？","options":["急性肾炎","泌尿系感染","肾病综合征","慢性肾衰"],"answer":1,"explanation":"膀胱刺激征由泌尿系感染（膀胱炎、尿道炎）引起，也可为结石、结核表现。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1683","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"上消化道出血量达多少可出现黑便？","options":["1000 ml","5 ml","50-70 ml","10 ml"],"answer":2,"explanation":"每日出血量>50-70ml出现黑便；>5ml可出现粪便隐血阳性；胃内积血250-300ml可呕血。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1684","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呕血提示胃内积血量至少为？","options":["50 ml","250-300 ml","100 ml","1000 ml"],"answer":1,"explanation":"胃内积血达250-300ml可引起呕血。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1685","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"周围血中网织红细胞增多提示？","options":["骨髓造血功能活跃（如溶血、失血后）","骨髓造血功能衰竭","缺铁未纠正","再生障碍性贫血"],"answer":0,"explanation":"网织红细胞升高提示骨髓红系造血活跃，见于溶血性贫血、急性失血、有效治疗后。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1686","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中性粒细胞增多最常见的原因是？","options":["急性感染（尤其化脓性细菌）","病毒感染","再生障碍性贫血","脾功能亢进"],"answer":0,"explanation":"中性粒细胞增多常见于化脓性细菌感染；病毒感染多致淋巴细胞增多。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1687","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"嗜酸性粒细胞增多常见于？","options":["化脓性感染","过敏性疾病和寄生虫感染","病毒性肝炎","再生障碍性贫血"],"answer":1,"explanation":"嗜酸性粒细胞增多见于过敏（哮喘、荨麻疹）和寄生虫感染（钩虫、血吸虫等）。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1688","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"淋巴细胞增多常见于？","options":["败血症","化脓性感染","寄生虫病","病毒感染（如传染性单核细胞增多症）"],"answer":3,"explanation":"病毒感染时淋巴细胞增多；化脓菌感染时中性粒细胞增多。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1689","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"红细胞沉降率（血沉）增快的原因不包括？","options":["感染、结核、风湿活动","红细胞增多症","恶性肿瘤","组织损伤"],"answer":1,"explanation":"血沉增快见于炎症、结核、风湿、肿瘤、组织损伤等；红细胞增多症血沉减慢。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1690","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常成人血小板参考范围是？","options":["(300-500)×10⁹/L","(50-100)×10⁹/L","(100-300)×10⁹/L","(10-30)×10⁹/L"],"answer":2,"explanation":"正常血小板计数为(100-300)×10⁹/L，<100×10⁹/L为血小板减少。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1691","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常人血清白蛋白/球蛋白（A/G）比值为？","options":["0.5-1:1","1.5-2.5:1","3-5:1","5-10:1"],"answer":1,"explanation":"血清白蛋白35-55g/L，球蛋白20-30g/L，A/G比值1.5-2.5:1，肝硬化时倒置。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1692","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血清总胆红素正常参考值是？","options":["1.7-3.4 μmol/L","34-170 μmol/L","3.4-17.1 μmol/L","50-100 μmol/L"],"answer":2,"explanation":"总胆红素正常3.4-17.1μmol/L，>17.1μmol/L为黄疸（隐性黄疸17.1-34.2）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1693","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"丙氨酸氨基转移酶（ALT）升高最常见于？","options":["骨骼肌损伤","心肌梗死","肝细胞损伤","肾病"],"answer":2,"explanation":"ALT主要存在于肝细胞内，肝细胞损伤时释放入血，是肝损害最敏感指标之一。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1694","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血肌酐升高的主要意义是？","options":["胰腺炎","肝功能减退","心肌损伤","肾小球滤过功能减退"],"answer":3,"explanation":"血肌酐反映肾小球滤过功能，明显升高提示肾功能不全。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1695","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"空腹血糖的正常参考值是？","options":["3.9-6.1 mmol/L","6.1-7.8 mmol/L","7.8-11.1 mmol/L","2.8-3.9 mmol/L"],"answer":0,"explanation":"空腹血糖3.9-6.1mmol/L为正常；≥7.0mmol/L考虑糖尿病（需复查）。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1696","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"诊断糖尿病的空腹血糖标准是？","options":["≥11.1 mmol/L（空腹）","≥6.1 mmol/L","≥7.0 mmol/L","≥5.6 mmol/L"],"answer":2,"explanation":"空腹血糖≥7.0mmol/L或餐后2小时≥11.1mmol/L，或有症状+随机血糖≥11.1mmol/L可诊断糖尿病。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1697","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"口服葡萄糖耐量试验（OGTT）2小时血糖≥多少可诊断糖尿病？","options":["6.1 mmol/L","7.8 mmol/L","11.1 mmol/L","9.0 mmol/L"],"answer":2,"explanation":"OGTT 2小时血糖≥11.1mmol/L可诊断糖尿病；7.8-11.1为糖耐量减低。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1698","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血清钾正常参考值是？","options":["5.5-6.5 mmol/L","2.5-3.5 mmol/L","3.5-5.5 mmol/L","6.5-7.5 mmol/L"],"answer":2,"explanation":"血钾3.5-5.5mmol/L；<3.5为低钾，>5.5为高钾。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1699","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低钾血症最早的心电图表现是？","options":["P波消失","T波高尖","QRS增宽","T波低平、U波增高"],"answer":3,"explanation":"低钾血症心电图早期T波低平、U波出现或增高，重者ST段下移。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1700","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高钾血症最危险的表现是？","options":["四肢麻木","心室颤动、心脏停搏","恶心呕吐","嗜睡"],"answer":1,"explanation":"高钾血症抑制心肌，严重者室颤或停搏，需紧急降钾处理。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1701","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"血清钠正常参考值是？","options":["155-165 mmol/L","125-135 mmol/L","145-155 mmol/L","135-145 mmol/L"],"answer":3,"explanation":"血钠135-145mmol/L；<135为低钠血症。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1702","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"动脉血气分析中，pH正常参考范围是？","options":["7.45-7.55","7.25-7.35","7.35-7.45","7.15-7.25"],"answer":2,"explanation":"动脉血pH正常7.35-7.45；<7.35为酸中毒，>7.45为碱中毒。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1703","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅰ型呼吸衰竭的血气特点是？","options":["PaO₂<60mmHg伴PaCO₂>50mmHg","PaO₂<60mmHg，PaCO₂正常或降低","PaO₂正常，PaCO₂升高","PaO₂>60mmHg"],"answer":1,"explanation":"Ⅰ型呼衰为低氧血症型（换气障碍），PaO₂<60mmHg不伴CO₂潴留；Ⅱ型伴PaCO₂>50mmHg。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1704","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅱ型呼吸衰竭的血气诊断标准是？","options":["仅PaCO₂>50mmHg","仅PaO₂<60mmHg","PaO₂<60mmHg且PaCO₂>50mmHg","pH<7.35"],"answer":2,"explanation":"Ⅱ型呼衰为低氧伴高碳酸血症（通气障碍），需同时满足两条标准。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1705","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心电图上反映心房除极的波是？","options":["T波","QRS波群","P波","U波"],"answer":2,"explanation":"P波代表心房除极；QRS代表心室除极；T波代表心室复极。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1706","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心电图上QRS波群代表？","options":["房室传导","心房除极","心室复极","心室除极"],"answer":3,"explanation":"QRS波群反映心室除极电位变化；T波为心室复极。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1707","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常窦性心律的心电图特征不包括？","options":["P-R间期>0.20秒","P波在Ⅰ、Ⅱ、aVF导联直立","频率60-100次/分","P-P间期规则"],"answer":0,"explanation":"正常P-R间期0.12-0.20秒，>0.20秒为一度房室传导阻滞。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1708","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死心电图最有诊断价值的表现是？","options":["窦性心动过速","ST段压低","T波倒置","ST段弓背向上抬高伴病理性Q波"],"answer":3,"explanation":"ST段弓背向上抬高、病理性Q波、T波动态演变是急性心梗的特征性心电图改变。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1709","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死早期（数小时内）最常见的心律失常是？","options":["心房颤动","房室传导阻滞","室性早搏和室性心动过速","窦性心动过缓"],"answer":2,"explanation":"急性心梗早期以室性心律失常（室早、室速）最常见，可发展为室颤。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1710","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心房颤动的心电图特点是？","options":["P-R间期延长","P波消失代之以F波、R-R规则","P波消失，代之以f波，R-R间期绝对不规则","QRS宽大畸形"],"answer":2,"explanation":"房颤心电图：P波消失、f波（350-600次/分）、R-R绝对不齐。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1711","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心室颤动的心电图特点是？","options":["P波消失","QRS-T完全消失，代之以不规则波动","R-R间期规则","ST段抬高"],"answer":1,"explanation":"室颤为最严重心律失常，QRS-T波群消失，出现不规则波动，需立即除颤。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1712","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"一度房室传导阻滞的心电图表现是？","options":["P波与QRS完全无关","部分P波后无QRS波","P-R间期>0.20秒，P波后均有QRS波","心室率40次/分"],"answer":2,"explanation":"一度房室传导阻滞仅有P-R间期延长（>0.20秒），无QRS脱落。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1713","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"三度房室传导阻滞的心电图特点是？","options":["部分P波后无QRS","P-R间期逐渐延长","P波与QRS波群完全无关，心房率>心室率","P-R间期固定延长"],"answer":2,"explanation":"三度（完全性）房室传导阻滞心房心室各自独立，P波与QRS无关，需起搏治疗。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1714","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"室性早搏的心电图特点是？","options":["P-R间期延长","提前出现窄QRS波前有P波","提前出现的宽大畸形QRS波，其前无P波","R-R间期绝对规则"],"answer":2,"explanation":"室性早搏：提前宽大畸形QRS、T波反向、代偿间歇完全。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1715","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心房扑动的心电图特征是？","options":["P-R延长","f波","P波消失代之以锯齿状F波（250-350次/分）","QRS畸形"],"answer":2,"explanation":"房扑见锯齿状F波，房室传导常呈2:1或4:1。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1716","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"左心室肥大的心电图表现是？","options":["RV₅+SV₁≥4.0mV（男）","RV₁+SV₅≥4.0mV","P波高尖","病理性Q波"],"answer":0,"explanation":"左室肥大：RV₅+SV₁≥4.0mV（男）或≥3.5mV（女），伴电轴左偏。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1717","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"右心室肥大的心电图表现是？","options":["RV₅+SV₁≥4.0mV","RV₁+SV₅≥1.2mV，电轴右偏","P波增宽","T波高尖"],"answer":1,"explanation":"右室肥大：RV₁增高、RV₁+SV₅≥1.2mV、电轴右偏、V₁导联R/S>1。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1718","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"二尖瓣型P波提示？","options":["左心房肥大","右心房肥大","左心室肥大","右心室肥大"],"answer":0,"explanation":"二尖瓣型P波（P波增宽>0.12秒、双峰）提示左房肥大，见于二尖瓣狭窄。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1719","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺型P波提示？","options":["心包积液","左心房肥大","右心室肥大","右心房肥大"],"answer":3,"explanation":"肺型P波（P波高尖≥0.25mV，Ⅱ、Ⅲ、aVF明显）提示右房肥大，见于慢性肺心病。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1720","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"X线检查中，胸腔积液量达多少可显示肋膈角变钝？","options":["约200-300 ml","50 ml","1000 ml","1500 ml"],"answer":0,"explanation":"胸腔积液200-300ml时X线显示肋膈角变钝；中等量积液见外高内低弧形影。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1721","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"大量胸腔积液的X线表现是？","options":["肺门影缩小","纵隔向患侧移位","双肺透亮度增加","患侧密度增高、纵隔向健侧移位"],"answer":3,"explanation":"大量胸腔积液推挤纵隔向健侧移位；肺不张时纵隔向患侧移位。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1722","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阻塞性肺气肿的X线表现是？","options":["双肺透亮度增加、膈肌低平","双肺透亮度降低","膈肌抬高","纵隔向患侧移位"],"answer":0,"explanation":"肺气肿时肺含气增多，透亮度增加、膈肌下降、肋间隙增宽、心影狭长。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1723","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹部X线平片见膈下游离气体提示？","options":["肠梗阻","胃肠道穿孔","急性胰腺炎","肝破裂（无空腔脏器损伤）"],"answer":1,"explanation":"膈下游离气体是胃肠道穿孔的特异性X线征象。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1724","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肠梗阻典型的X线表现是？","options":["双膈下积气","膈下游离气体","膈肌抬高","肠管扩张积气伴多个阶梯状气液平面"],"answer":3,"explanation":"肠梗阻X线见肠管扩张、积气积液，立位见多发阶梯状液平面。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1725","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性胰腺炎诊断最有价值的血清学检查是？","options":["血肌酐","血淀粉酶和脂肪酶","血钙（早期诊断价值有限）","血常规"],"answer":1,"explanation":"血淀粉酶（发病2-12小时升高）和脂肪酶（更特异）是急性胰腺炎主要诊断指标。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1726","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性胰腺炎时血淀粉酶升高的时间是？","options":["发病后3天","发病后1周","发病后立即","发病后2-12小时开始升高"],"answer":3,"explanation":"血淀粉酶发病2-12小时升高，24-48小时达高峰，持续3-5天。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1727","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"超声检查对下列哪种疾病最有诊断价值？","options":["胆结石","胃癌","结肠癌","胰腺癌（早期）"],"answer":0,"explanation":"超声对胆囊结石诊断准确率>95%，是首选检查。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1728","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中枢性面瘫与周围性面瘫的鉴别要点是？","options":["无区别","中枢性面瘫额纹消失","周围性面瘫只累及上面部","中枢性面瘫只累及下面部（额纹存在）"],"answer":3,"explanation":"中枢性面瘫（皮质脑干束损害）仅下面部瘫痪、额纹保留；周围性面瘫（面神经损害）同侧全部面肌瘫痪、额纹消失。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1729","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脑膜刺激征包括？","options":["肌张力增高","Babinski征、Oppenheim征","腱反射亢进","颈强直、Kernig征、Brudzinski征"],"answer":3,"explanation":"脑膜刺激征三项：颈强直、克氏征、布氏征，见于脑膜炎、蛛网膜下腔出血。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1730","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Babinski征（巴宾斯基征）阳性提示？","options":["小脑病变","下运动神经元损害","锥体束（上运动神经元）损害","周围神经病变"],"answer":2,"explanation":"Babinski征阳性为锥体束损害的重要体征，正常2岁以下婴儿可为阳性。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1731","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肌张力呈铅管样强直伴静止性震颤提示？","options":["帕金森病","小脑病变","周围神经病","癫痫"],"answer":0,"explanation":"帕金森病表现为静止性震颤、铅管样（齿轮样）肌张力增高、运动迟缓。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1732","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"共济运动检查中指鼻试验阳性提示？","options":["小脑病变或深感觉障碍","锥体束损害","周围神经损伤","大脑皮层病变"],"answer":0,"explanation":"指鼻试验、跟膝胫试验、快复轮替动作等检查共济运动，阳性提示小脑或深感觉病变。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1733","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"偏瘫的病变部位在？","options":["同侧小脑","对侧大脑半球（皮质运动区或内囊）","同侧脊髓","对侧小脑"],"answer":1,"explanation":"大脑半球病变引起对侧偏瘫（交叉支配），内囊损害致对侧偏瘫、偏身感觉障碍、偏盲（三偏征）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1734","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"三偏征（偏瘫、偏身感觉障碍、偏盲）提示病变在？","options":["脑干","内囊","小脑","脊髓"],"answer":1,"explanation":"内囊区病变（如脑出血）典型表现为三偏征。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1735","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腰椎穿刺脑脊液检查的禁忌证是？","options":["蛛网膜下腔出血","脑膜炎","颅内压显著增高（脑疝风险）","多发性硬化"],"answer":2,"explanation":"颅内压显著增高者腰穿可诱发脑疝，为相对禁忌，需先降颅压。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1736","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常脑脊液压力为？","options":["20-60 mmH₂O","80-180 mmH₂O","200-300 mmH₂O","300-400 mmH₂O"],"answer":1,"explanation":"脑脊液压力侧卧位正常80-180mmH₂O，>200mmH₂O为颅内压增高。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1737","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"化脓性脑膜炎脑脊液特点是？","options":["以淋巴细胞为主","外观清亮、糖正常","外观浑浊、白细胞显著升高（以中性粒细胞为主）、糖明显降低","蛋白正常"],"answer":2,"explanation":"化脑脑脊液浑浊或脓性、压力高、白细胞>1000×10⁶/L（中性为主）、蛋白高、糖低。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1738","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核性脑膜炎脑脊液特点是？","options":["以中性粒细胞为主","外观毛玻璃样、以淋巴细胞为主、糖和氯化物降低、蛋白升高","糖正常","外观脓性"],"answer":1,"explanation":"结脑脑脊液毛玻璃样、静置可有薄膜形成、淋巴细胞为主、蛋白高、糖和氯化物低。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1739","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒性脑炎脑脊液特点是？","options":["糖明显降低","外观清亮、以淋巴细胞为主、糖和氯化物正常","外观脓性","中性粒细胞为主"],"answer":1,"explanation":"病毒性脑炎脑脊液清亮、压力轻高、淋巴细胞为主、蛋白轻度升高、糖氯化物正常。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1740","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"蛛网膜下腔出血脑脊液特点是？","options":["黄变仅见于晚期（早期血性）","清亮","毛玻璃样","均匀一致血性脑脊液"],"answer":3,"explanation":"蛛网膜下腔出血脑脊液均匀血性、压力增高，数日后可黄变。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1741","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"视乳头水肿提示？","options":["青光眼早期","视神经萎缩","颅内压增高","高血压仅眼底动脉硬化"],"answer":2,"explanation":"视乳头水肿是颅内压增高的重要客观体征，伴视力一般无明显下降（早期）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1742","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"瞳孔对光反射消失提示？","options":["视神经萎缩（必然）","中脑或动眼神经损害（危重）","正常变异","仅结膜炎"],"answer":1,"explanation":"对光反射消失提示中脑损害或动眼神经麻痹，是判断昏迷深度和脑死亡的重要指标。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1743","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"双侧瞳孔针尖样缩小提示？","options":["癫痫发作","脑疝（单侧散大）","阿托品中毒","脑桥出血或吗啡、有机磷中毒"],"answer":3,"explanation":"针尖样瞳孔见于脑桥出血、吗啡类和有机磷中毒；单侧散大固定提示小脑幕切迹疝。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1744","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"单侧瞳孔散大、对光反射消失提示？","options":["糖尿病昏迷","脑桥出血","吗啡中毒","小脑幕切迹疝"],"answer":3,"explanation":"单侧瞳孔散大为颞叶钩回疝（小脑幕切迹疝）压迫动眼神经所致，需紧急降颅压。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1745","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"体格检查的基本方法包括？","options":["影像检查","问诊、查体、化验","望闻问切","视诊、触诊、叩诊、听诊、嗅诊"],"answer":3,"explanation":"体格检查五法：视、触、叩、听、嗅。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1746","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"深部触诊法主要用于检查？","options":["腹腔脏器和深部包块","皮肤温度","脉搏","浅表淋巴结"],"answer":0,"explanation":"深部触诊（深部滑行、双手、深压、冲击触诊）用于腹腔深部病变。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1747","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"叩诊呈鼓音见于？","options":["气胸（过清音或鼓音）","大量胸腔积液","肺实变","胃泡区和肠胀气"],"answer":3,"explanation":"鼓音见于含大量气体的空腔器官（胃泡、肠胀气）；肺实变呈浊音。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1748","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺实变的叩诊音是？","options":["过清音","鼓音","浊音或实音","清音"],"answer":2,"explanation":"肺实变（肺炎、肺不张）叩诊呈浊音或实音，语颤增强、病理性支气管呼吸音。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1749","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺气肿的叩诊音是？","options":["鼓音","浊音","实音","过清音"],"answer":3,"explanation":"肺气肿肺含气增多、弹性减弱，叩诊呈过清音，肺下界下移。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1750","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常肺部叩诊音是？","options":["鼓音","清音","浊音","过清音"],"answer":1,"explanation":"正常肺组织叩诊为清音；肝浊音界消失（鼓音）提示气腹或胃肠穿孔。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1751","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"湿啰音的特点是？","options":["与体位无关","呼气末明显、多变","干啰音的一种","吸气末明显、部位较固定、咳嗽后可消失或变化"],"answer":3,"explanation":"湿啰音（水泡音）为气道内液体经气流形成，吸气末明显，咳嗽后可变化。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1752","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"干啰音的特点是？","options":["仅见于胸腔积液","吸气末明显","固定不变","呼气相明显、部位多变、咳嗽后可消失"],"answer":3,"explanation":"干啰音由支气管狭窄产生，呼气明显、易变，哮鸣音为其典型。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1753","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"哮鸣音提示？","options":["肺实变","肺水肿","胸腔积液","支气管痉挛狭窄（哮喘）"],"answer":3,"explanation":"哮鸣音为高调干啰音，提示支气管痉挛狭窄，是哮喘的典型体征。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1754","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胸腔积液体征不包括？","options":["呼吸音减弱","患侧叩诊浊音","气管向健侧移位","患侧呼吸音增强"],"answer":3,"explanation":"胸腔积液患侧呼吸音减弱或消失，不会增强。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1755","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"气胸的体征是？","options":["患侧叩诊浊音","患侧叩诊鼓音、呼吸音减弱","气管向患侧移位","双肺满布湿啰音"],"answer":1,"explanation":"气胸患侧胸廓饱满、叩诊鼓音、呼吸音减弱，气管移向健侧。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1756","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"正常心尖搏动位于？","options":["左侧第3肋间","左侧第5肋间锁骨中线内0.5-1.0cm","胸骨左缘第4肋间","右侧第5肋间"],"answer":1,"explanation":"正常心尖搏动位于第5肋间左锁骨中线内0.5-1.0cm，搏动范围2.0-2.5cm。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1757","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心尖区闻及舒张期隆隆样杂音提示？","options":["室间隔缺损","二尖瓣关闭不全","主动脉瓣狭窄","二尖瓣狭窄"],"answer":3,"explanation":"二尖瓣狭窄特征性杂音为心尖区舒张期隆隆样杂音，伴第一心音亢进。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1758","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心尖区闻及收缩期粗糙吹风样杂音提示？","options":["肺动脉瓣狭窄","二尖瓣狭窄","主动脉瓣关闭不全","二尖瓣关闭不全"],"answer":3,"explanation":"二尖瓣关闭不全为心尖区3/6级以上收缩期吹风样杂音，向左腋下传导。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1759","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"主动脉瓣第二听诊区闻及舒张期叹气样杂音提示？","options":["二尖瓣狭窄","主动脉瓣狭窄","主动脉瓣关闭不全","三尖瓣关闭不全"],"answer":2,"explanation":"主动脉瓣关闭不全在胸骨左缘第3肋间（第二听诊区）闻及舒张期叹气样杂音。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1760","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"主动脉瓣区闻及收缩期喷射样杂音提示？","options":["主动脉瓣狭窄","主动脉瓣关闭不全","二尖瓣关闭不全","房间隔缺损"],"answer":0,"explanation":"主动脉瓣狭窄在胸骨右缘第2肋间闻及收缩期喷射样杂音，向颈部传导。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1761","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"第一心音增强见于？","options":["二尖瓣关闭不全","二尖瓣狭窄","主动脉瓣关闭不全","心肌梗死"],"answer":1,"explanation":"二尖瓣狭窄时左房压高、心室充盈时间延长，瓣膜位置低，第一心音亢进。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1762","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"第二心音逆分裂（反常分裂）提示？","options":["正常变异","完全性右束支传导阻滞","完全性左束支传导阻滞或主动脉瓣狭窄","二尖瓣狭窄"],"answer":2,"explanation":"第二心音逆分裂（吸气时分裂反而消失）见于左束支阻滞、主动脉瓣狭窄。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1763","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"收缩期杂音3/6级以上提示？","options":["与心脏病无关","均为生理性","多为器质性心脏病","仅见于儿童"],"answer":2,"explanation":"3/6级以上收缩期杂音多为器质性；2/6级以下可为功能性。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1764","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹水患者移动性浊音阳性提示腹腔积液至少为？","options":["500 ml","100 ml","300 ml","1000 ml以上"],"answer":3,"explanation":"腹腔积液>1000ml可叩出移动性浊音；少量积液需超声检查。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1765","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹膜刺激征（压痛、反跳痛、肌紧张）提示？","options":["肠易激综合征","消化不良","慢性胃炎","急性腹膜炎"],"answer":3,"explanation":"腹膜刺激征为急性腹膜炎的重要体征，提示腹膜受炎症刺激。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1766","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Murphy征（墨菲征）阳性提示？","options":["胃溃疡","急性胰腺炎","急性阑尾炎","急性胆囊炎"],"answer":3,"explanation":"墨菲征阳性（深压胆囊点时患者因疼痛屏气）提示急性胆囊炎。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1767","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性阑尾炎最重要的体征是？","options":["脐周压痛","全腹压痛","右上腹压痛","麦氏点（右下腹）固定压痛"],"answer":3,"explanation":"麦氏点（脐与右髂前上棘连线中外1/3交界处）固定压痛是阑尾炎最重要体征。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1768","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝掌和蜘蛛痣的形成机制是？","options":["凝血功能障碍","雄激素过多","肝功能减退致雌激素灭活减少","门脉高压直接作用"],"answer":2,"explanation":"肝脏对雌激素灭活减少，雌激素增多使小动脉扩张，形成蜘蛛痣、肝掌。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1769","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"脾肿大伴腹水、腹壁静脉曲张提示？","options":["肝硬化门脉高压","急性肝炎","脾功能亢进（单纯）","肝癌晚期"],"answer":0,"explanation":"门脉高压三联征：脾大、侧支循环建立（腹壁静脉曲张、食管胃底静脉曲张）、腹水。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1770","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹部包块伴肠鸣音亢进、气过水声提示？","options":["腹膜炎","麻痹性肠梗阻","机械性肠梗阻","消化不良"],"answer":2,"explanation":"机械性肠梗阻肠鸣音亢进（气过水声、金属音）；麻痹性肠梗阻肠鸣音消失。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1771","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肠鸣音消失（持续听诊3-5分钟未闻及）提示？","options":["急性腹膜炎或麻痹性肠梗阻","机械性肠梗阻","饥饿","腹泻"],"answer":0,"explanation":"肠鸣音消失见于急性腹膜炎、麻痹性肠梗阻、低血钾等。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1772","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"直肠指检对下列哪种疾病最有诊断价值？","options":["胃癌","直肠癌（低位）","肝癌","胰腺癌"],"answer":1,"explanation":"直肠指检可发现约70%的直肠癌（低位），是简便重要的检查。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1773","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"淋巴结触诊发现质地坚硬、固定、无压痛的包块提示？","options":["正常变异","淋巴结炎","结核性淋巴结炎","恶性肿瘤转移"],"answer":3,"explanation":"质硬、固定、无压痛、融合的淋巴结提示恶性肿瘤转移；质软、活动、压痛多为炎症。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1774","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲状腺触诊发现震颤伴血管杂音提示？","options":["单纯性甲状腺肿","甲状腺功能亢进","甲状腺癌","亚急性甲状腺炎"],"answer":1,"explanation":"甲亢时甲状腺血流丰富，触诊震颤、听诊血管杂音（特征性体征）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1775","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲状腺肿大伴疼痛、发热提示？","options":["单纯性甲状腺肿","亚急性甲状腺炎","甲状腺功能亢进","甲状腺癌"],"answer":1,"explanation":"亚急性甲状腺炎甲状腺肿痛、触痛明显，常有上感前驱史。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1776","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"杵状指（趾）常见于？","options":["慢性缺氧性疾病（支扩、肺脓肿、发绀型先心病）","贫血","高血压","糖尿病"],"answer":0,"explanation":"杵状指见于慢性缺氧（支扩、肺脓肿、肺心病、发绀型先心病）和感染性心内膜炎等。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1777","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"反甲（匙状甲）提示？","options":["缺铁性贫血","慢性缺氧","甲亢","痛风"],"answer":0,"explanation":"匙状甲（反甲）是缺铁性贫血的特征表现之一。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1778","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"眼睑水肿伴蛋白尿提示？","options":["心源性水肿","肾性水肿","肝性水肿","营养不良性水肿"],"answer":1,"explanation":"肾性水肿晨起眼睑颜面肿，伴蛋白尿、血尿。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1779","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"黄疸伴胆囊肿大（Courvoisier征阳性）提示？","options":["胰头癌（无痛性进行性黄疸）","胆总管结石（绞痛）","急性胆囊炎","肝细胞性黄疸"],"answer":0,"explanation":"胰头癌压迫胆总管致无痛性进行性黄疸、胆囊肿大（库瓦济埃征）。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1780","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"上腹部剧烈疼痛向腰背部放射提示？","options":["急性胰腺炎","急性胃炎","消化不良","肠易激综合征"],"answer":0,"explanation":"急性胰腺炎疼痛向腰背部呈带状放射，弯腰抱膝位可减轻。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1781","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"呕血伴剧烈腹痛、发热提示？","options":["胃癌（早期）","食管静脉曲张破裂","消化性溃疡（单纯）","胆道出血（胆绞痛+发热）"],"answer":3,"explanation":"胆道出血三联征：腹痛、黄疸、出血（呕血或黑便），常伴发热。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-1782","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"意识障碍伴烂苹果味呼吸提示？","options":["糖尿病酮症酸中毒","肝性脑病","尿毒症","酒精中毒"],"answer":0,"explanation":"酮症酸中毒呼气有烂苹果味（丙酮）；肝性脑病为肝臭味；尿毒症为氨味。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1783","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"意识障碍伴氨味（尿味）呼吸提示？","options":["肝性脑病","糖尿病酮症","尿毒症","肺性脑病"],"answer":2,"explanation":"尿毒症呼气有氨味（尿味），伴贫血、出血倾向等。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1784","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"意识障碍伴肝臭味提示？","options":["有机磷中毒","尿毒症","酮症酸中毒","肝性脑病"],"answer":3,"explanation":"肝性脑病呼气有肝臭味（硫醇类），伴扑翼样震颤。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1785","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"有机磷中毒的呼吸气味是？","options":["大蒜味","烂苹果味","氨味","肝臭味"],"answer":0,"explanation":"有机磷农药中毒呼气和呕吐物有大蒜味，伴瞳孔缩小、肌束震颤、分泌物增多。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-1786","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"意识障碍伴口唇樱桃红色提示？","options":["严重贫血","糖尿病酮症","亚硝酸盐中毒","一氧化碳中毒"],"answer":3,"explanation":"CO中毒皮肤黏膜呈樱桃红色（碳氧血红蛋白），有明确接触史。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1787","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"意识障碍伴口唇发绀（青紫色）提示？","options":["亚硝酸盐中毒（高铁血红蛋白血症）","一氧化碳中毒","酒精中毒","低血糖"],"answer":0,"explanation":"亚硝酸盐中毒高铁血红蛋白血症致口唇发绀，用亚甲蓝解救。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1788","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低血糖昏迷的表现不包括？","options":["瞳孔散大、皮肤干燥","心悸、出汗、手抖","意识模糊","血糖<2.8mmol/L"],"answer":0,"explanation":"低血糖表现为交感兴奋（心悸、出汗、手抖）和神经缺糖症状；瞳孔散大、皮肤干燥是阿托品化或抗胆碱能表现。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1789","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"昏迷患者瞳孔散大、对光反射消失，最可能的诊断是？","options":["深昏迷或脑干功能衰竭","浅昏迷","嗜睡","癔症"],"answer":0,"explanation":"深昏迷时瞳孔散大、对光反射消失，提示脑干功能严重受损。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-1790","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性阻塞性肺疾病（COPD）最重要的危险因素是？","options":["感染","空气污染","职业粉尘","吸烟"],"answer":3,"explanation":"吸烟是COPD最重要的发病因素，戒烟是延缓病情进展的最有效措施。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1791","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"COPD的诊断金标准是？","options":["肺功能检查（吸入支气管舒张剂后FEV₁/FVC<70%）","胸片","血气分析","胸部CT"],"answer":0,"explanation":"肺功能是COPD诊断的金标准：吸入舒张剂后FEV₁/FVC<70%提示持续气流受限。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1792","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"COPD急性加重最常见的诱因是？","options":["情绪激动","气候变化","呼吸道感染","饮食不当"],"answer":2,"explanation":"呼吸道感染（病毒或细菌）是COPD急性加重的最常见诱因。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1793","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"支气管哮喘的本质是？","options":["支气管肿瘤","细菌感染","气道慢性炎症（多种细胞参与）","肺实质破坏"],"answer":2,"explanation":"哮喘为气道慢性炎症性疾病，由嗜酸性粒细胞、肥大细胞等多种细胞参与，气道高反应性为特征。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1794","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"支气管哮喘的典型表现是？","options":["咯血","持续性吸气性呼吸困难","咳嗽伴大量脓痰","发作性呼气性呼吸困难伴广泛哮鸣音"],"answer":3,"explanation":"哮喘典型表现为反复发作的喘息、呼气性呼吸困难，双肺广泛哮鸣音，可自行或用药后缓解。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1795","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"哮喘发作时首选的缓解药物是？","options":["抗生素","糖皮质激素口服","氨茶碱静滴","短效β₂受体激动剂（沙丁胺醇）"],"answer":3,"explanation":"沙丁胺醇等短效β₂激动剂迅速舒张支气管，是缓解急性发作的首选。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1796","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"哮喘长期控制的首选药物是？","options":["吸入性糖皮质激素","口服泼尼松","静脉甲泼尼龙","白三烯调节剂"],"answer":0,"explanation":"吸入性糖皮质激素是哮喘长期控制（抗炎）的首选药物。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1797","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"哮喘持续状态（重度发作）的处理不包括？","options":["雾化β₂激动剂","吸氧","立即使用吗啡镇静","静脉糖皮质激素"],"answer":2,"explanation":"吗啡抑制呼吸并释放组胺加重支气管痉挛，哮喘禁用。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1798","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"支气管扩张的典型临床表现是？","options":["刺激性干咳","慢性咳嗽、大量脓痰、反复咯血","胸痛伴呼吸困难","发热伴皮疹"],"answer":1,"explanation":"支扩三联征：慢性咳嗽、大量脓痰（静置分层）、反复咯血。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1799","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"支气管扩张确诊的首选检查是？","options":["高分辨率CT（HRCT）","胸片","支气管造影","肺功能"],"answer":0,"explanation":"HRCT显示支气管扩张的柱状或囊状改变，是确诊首选。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1800","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"社区获得性肺炎最常见的病原体是？","options":["铜绿假单胞菌","金黄色葡萄球菌","肺炎链球菌","厌氧菌"],"answer":2,"explanation":"社区获得性肺炎以肺炎链球菌最常见。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1801","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺炎链球菌肺炎的典型表现是？","options":["刺激性干咳","寒战高热、咳嗽、铁锈色痰","大量脓臭痰","咯血伴消瘦"],"answer":1,"explanation":"肺炎链球菌肺炎起病急骤、寒战高热、咳嗽、咳铁锈色痰，肺实变体征。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1802","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺炎链球菌肺炎的首选抗生素是？","options":["万古霉素","庆大霉素","四环素","青霉素G"],"answer":3,"explanation":"肺炎链球菌对青霉素敏感（耐青霉素株用头孢曲松或呼吸喹诺酮），首选青霉素G。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1803","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"金黄色葡萄球菌肺炎的特点是？","options":["铁锈色痰","易形成肺脓肿和脓胸","多见于健康青年","首选青霉素G"],"answer":1,"explanation":"金葡菌肺炎毒力强、易化脓，形成肺脓肿、脓胸，首选耐酶青霉素（苯唑西林）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1804","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺结核的主要传播途径是？","options":["消化道","呼吸道飞沫传播","血液","接触传播"],"answer":1,"explanation":"肺结核经呼吸道飞沫传播，开放性肺结核患者是主要传染源。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1805","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺结核确诊的最重要检查是？","options":["血沉","PPD试验","胸片","痰结核菌检查（涂片/培养）"],"answer":3,"explanation":"痰中找到结核分枝杆菌是确诊肺结核的最重要依据。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1806","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺结核化疗的原则是？","options":["单药长程","早期、联合、适量、规律、全程","症状消失即停药","大剂量冲击"],"answer":1,"explanation":"结核化疗十字原则：早期、联合、适量、规律、全程，防止复发和耐药。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1807","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺结核短程化疗的疗程一般为？","options":["2年","3个月","1年","6-9个月"],"answer":3,"explanation":"初治肺结核标准短程化疗6-9个月（2HRZE/4HR等方案）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1808","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"原发性肺结核的好发人群是？","options":["HIV患者","老年人","糖尿病患者","儿童"],"answer":3,"explanation":"原发性肺结核多见于儿童（初次感染），原发综合征为典型表现。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1809","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"继发性肺结核最常见的类型是？","options":["血行播散型肺结核","浸润性肺结核","结核性胸膜炎","原发综合征"],"answer":1,"explanation":"继发性肺结核以浸润性肺结核最常见，多见于成人。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1810","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺癌最常见的组织学类型是？","options":["小细胞癌","鳞癌","腺癌（近年最常见）","大细胞癌"],"answer":2,"explanation":"肺癌中腺癌已超过鳞癌成为最常见类型；小细胞癌恶性度最高、对化疗敏感。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1811","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺癌的首选筛查方法是？","options":["胸片","低剂量螺旋CT","痰细胞学","肿瘤标志物"],"answer":1,"explanation":"低剂量螺旋CT是肺癌高危人群筛查的首选，能发现早期病变。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1812","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中央型肺癌最常见的组织类型是？","options":["腺癌","鳞癌（与吸烟关系密切）","小细胞癌","大细胞癌"],"answer":1,"explanation":"中央型肺癌以鳞癌和小细胞癌多见；周围型以腺癌多见。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1813","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"小细胞肺癌的特点是？","options":["恶性度高、生长快、对放化疗敏感","生长慢","对放化疗不敏感","首选手术"],"answer":0,"explanation":"小细胞肺癌恶性度高、早期转移，以放化疗为主（手术作用有限）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1814","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胸腔积液中，渗出液的特点是？","options":["蛋白<25g/L","外观清亮透明","蛋白含量高、比重>1.018、细胞数多","比重<1.015"],"answer":2,"explanation":"渗出液蛋白>30g/L、比重>1.018、细胞数多，见于炎症、肿瘤；漏出液相反。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1815","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"结核性胸膜炎胸腔积液的特点是？","options":["糖正常（一般）","以中性粒细胞为主","以淋巴细胞为主、ADA升高、蛋白高","pH明显升高"],"answer":2,"explanation":"结核性胸水为渗出液，淋巴细胞为主、ADA（腺苷脱氨酶）>45U/L有诊断价值。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1816","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"癌性胸腔积液的特点是？","options":["以中性粒细胞为主","ADA明显升高","血性积液、CEA升高、可找到癌细胞","糖升高"],"answer":2,"explanation":"癌性胸水常为血性，CEA升高，脱落细胞学找到癌细胞可确诊。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1817","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性心力衰竭最常见的病因是？","options":["先天性心脏病","心肌病","心脏瓣膜病","冠心病和高血压"],"answer":3,"explanation":"冠心病和高血压是我国慢性心衰最主要的病因。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1818","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"左心衰竭的主要表现是？","options":["肝大","下肢水肿","颈静脉怒张","呼吸困难（劳力性→夜间阵发性→端坐呼吸）"],"answer":3,"explanation":"左心衰竭以肺淤血为主，表现为呼吸困难（进行性加重）和咳嗽咳痰。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1819","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"右心衰竭的主要表现是？","options":["夜间阵发性呼吸困难","体循环淤血（颈静脉怒张、肝大、下肢水肿）","粉红色泡沫痰","端坐呼吸"],"answer":1,"explanation":"右心衰竭以体循环淤血为主：颈静脉怒张、肝大压痛、下肢凹陷性水肿。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1820","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性左心衰竭的典型表现是？","options":["突发严重呼吸困难、咳粉红色泡沫痰","下肢水肿","颈静脉怒张","肝区疼痛"],"answer":0,"explanation":"急性左心衰（肺水肿）：突发呼吸困难、端坐呼吸、粉红色泡沫痰、满肺湿啰音。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1821","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性左心衰竭的首选处理是？","options":["立即抗生素","立即洋地黄","高流量吸氧、坐位、利尿、扩血管","立即补液"],"answer":2,"explanation":"急性肺水肿：端坐位、高流量吸氧（可加酒精消泡）、快速利尿（呋塞米）、扩血管（硝酸甘油）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1822","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"洋地黄中毒最常见的心律失常是？","options":["室性早搏（二联律）","房室传导阻滞","窦性心动过缓","房颤"],"answer":0,"explanation":"洋地黄中毒最常见室性早搏（尤其二联律），特征性表现为快速心律失常伴传导阻滞。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1823","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"洋地黄中毒的处理是？","options":["加大剂量","立即停药、补钾、必要时用苯妥英钠","立即电复律","继续观察"],"answer":1,"explanation":"洋地黄中毒立即停药、纠正低钾，室性心律失常用苯妥英钠或利多卡因。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1824","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心衰患者使用β受体阻滞剂的原则是？","options":["小剂量开始、逐渐加量、长期维持","大剂量冲击","急性期立即大剂量","症状加重时加量"],"answer":0,"explanation":"β受体阻滞剂改善心衰预后，须小剂量起始、缓慢加量、长期维持，急性失代偿期慎用。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1825","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"心衰患者利尿剂的主要作用是？","options":["抗心律失常","增强心肌收缩力","减慢心率","减轻水钠潴留、降低心脏前负荷"],"answer":3,"explanation":"利尿剂排钠排水，减轻前负荷和淤血症状，是心衰基础治疗。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1826","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压的诊断标准是？","options":["舒张压≥85mmHg","一次测量≥140/90mmHg","收缩压≥130mmHg","非同日3次测量收缩压≥140mmHg和/或舒张压≥90mmHg"],"answer":3,"explanation":"高血压诊断标准：非同日3次测量≥140/90mmHg。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1827","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压最常见的心脏并发症是？","options":["心包积液","左心室肥厚和心力衰竭","感染性心内膜炎","心房黏液瘤"],"answer":1,"explanation":"长期高血压致左心室肥厚、扩大，最终心力衰竭。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1828","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压最严重的并发症是？","options":["眼底出血","脑卒中（脑出血、脑梗死）","肾功能不全","主动脉夹层"],"answer":1,"explanation":"脑卒中是高血压最严重的并发症，是我国高血压患者主要死因。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1829","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压急症的处理原则是？","options":["立即口服降压药","静脉降压药物迅速降压（1小时内平均压降低不超过25%）","快速降至正常低值","观察等待"],"answer":1,"explanation":"高血压急症静脉用药，初期1小时内平均动脉压下降不超过25%，防止重要器官灌注不足。","exam":"医疗编","__sub":"内科临床","diff":3,"id":"yl-1830","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压患者降压治疗的目标值（一般患者）是？","options":["<140/90 mmHg","<160/100 mmHg","<120/70 mmHg（所有患者）","<150/100 mmHg"],"answer":0,"explanation":"一般高血压患者血压控制目标<140/90mmHg，耐受良好或高危者可<130/80mmHg。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1831","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压伴痛风患者不宜使用？","options":["卡托普利","氨氯地平","氢氯噻嗪","美托洛尔"],"answer":2,"explanation":"噻嗪类利尿药升高血尿酸，痛风患者慎用或禁用。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1832","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高血压伴双侧肾动脉狭窄患者禁用？","options":["钙拮抗剂","ACEI/ARB","β受体阻滞剂","利尿剂"],"answer":1,"explanation":"双侧肾动脉狭窄者用ACEI/ARB可致急性肾衰竭，禁用。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1833","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"冠心病的最重要危险因素是？","options":["血脂异常（LDL-C升高）","年龄","性别","家族史"],"answer":0,"explanation":"LDL-C升高是动脉粥样硬化最重要的危险因素，是降脂治疗主要目标。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1834","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"冠心病的确诊检查是？","options":["心电图","冠状动脉造影","运动平板试验","心脏彩超"],"answer":1,"explanation":"冠脉造影是冠心病诊断的金标准，可明确狭窄部位和程度。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1835","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"稳定型心绞痛发作时的处理是？","options":["立即休息、舌下含服硝酸甘油","口服阿司匹林","静脉输液","立即溶栓"],"answer":0,"explanation":"心绞痛发作立即停止活动、舌下含服硝酸甘油，1-2分钟缓解。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1836","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"变异型心绞痛的首选药物是？","options":["β受体阻滞剂","钙通道阻滞剂（地尔硫䓬）","利尿剂","ACEI"],"answer":1,"explanation":"变异型心绞痛由冠脉痉挛引起，钙通道阻滞剂为首选；β受体阻滞剂可加重痉挛。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1837","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死的典型表现是？","options":["胸痛持续数秒","阵发性胸闷","胸骨后剧烈持久的压榨性疼痛，硝酸甘油不能缓解","与呼吸有关的刺痛"],"answer":2,"explanation":"心梗疼痛剧烈持久（>30分钟），休息和含服硝酸甘油不缓解，伴大汗、濒死感。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1838","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死诊断最有价值的血液学指标是？","options":["肌钙蛋白（cTnI/cTnT）","肌酸激酶（CK）","血常规","血沉"],"answer":0,"explanation":"肌钙蛋白特异性、敏感性最高，是心梗诊断的首选心肌标志物。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1839","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死发病后肌钙蛋白升高的时间是？","options":["1周后升高","立即升高","24小时后升高","3-4小时开始升高，持续7-10天"],"answer":3,"explanation":"肌钙蛋白发病3-4小时升高，11-24小时达高峰，持续7-10天。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1840","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性ST段抬高型心肌梗死的首选再灌注治疗是？","options":["静脉溶栓（无条件行PCI时）","口服阿司匹林观察","发病12小时内急诊PCI（或溶栓）","冠脉搭桥"],"answer":2,"explanation":"STEMI首选发病12小时内急诊PCI；无条件时发病12小时内（最好3小时内）静脉溶栓。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1841","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死患者绝对卧床的时间一般为？","options":["1个月","1周","24小时即可下床","发病后12小时内绝对卧床"],"answer":3,"explanation":"急性心梗12小时内绝对卧床、心电监护，之后根据病情逐步活动。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1842","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性心肌梗死最常见的死亡原因是？","options":["心室颤动（心律失常）","心源性休克","心力衰竭","心脏破裂"],"answer":0,"explanation":"急性心梗早期（24小时内）死亡原因以室颤为主，需心电监护、除颤备用。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1843","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"风湿性心脏病最常受累的瓣膜是？","options":["肺动脉瓣","主动脉瓣","三尖瓣","二尖瓣"],"answer":3,"explanation":"风心病以二尖瓣最常受累（狭窄最典型），其次为主动脉瓣。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1844","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"二尖瓣狭窄的典型体征是？","options":["心尖区收缩期杂音","心尖区舒张期隆隆样杂音","主动脉瓣区舒张期杂音","水冲脉"],"answer":1,"explanation":"二尖瓣狭窄：心尖区舒张期隆隆样杂音、第一心音亢进、开瓣音。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1845","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"二尖瓣狭窄最常见的并发症是？","options":["感染性心内膜炎","心房颤动","栓塞","肺部感染"],"answer":1,"explanation":"房颤是二尖瓣狭窄最常见并发症，发生后血栓栓塞风险增加。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1846","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"感染性心内膜炎最常见的病原体是？","options":["结核杆菌","金黄色葡萄球菌（静脉药瘾者）","大肠埃希菌","草绿色链球菌（自体瓣膜）"],"answer":3,"explanation":"自体瓣膜感染性心内膜炎以草绿色链球菌最常见；静脉药瘾者以金葡菌常见。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1847","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"感染性心内膜炎确诊依据是？","options":["血培养阳性（多次）","发热","心脏杂音","血沉增快"],"answer":0,"explanation":"血培养阳性是感染性心内膜炎最重要的确诊依据，需多次采血培养。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1848","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒性心肌炎最常见的病原体是？","options":["乙肝病毒","流感病毒","柯萨奇B组病毒","EB病毒"],"answer":2,"explanation":"病毒性心肌炎以柯萨奇B组病毒最常见，发病前1-3周常有病毒感染前驱症状。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1849","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"病毒性心肌炎的治疗不包括？","options":["营养心肌","休息（最重要）","早期大剂量糖皮质激素常规使用","对症处理"],"answer":2,"explanation":"病毒性心肌炎以休息、营养心肌、对症为主，糖皮质激素不常规使用（重症或自身免疫参与时考虑）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1850","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性胃炎最常见的病因是？","options":["幽门螺杆菌感染","长期饮酒","胆汁反流","自身免疫"],"answer":0,"explanation":"幽门螺杆菌感染是慢性胃炎（活动性）最主要的病因。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1851","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性胃炎确诊的检查是？","options":["胃镜及活检","钡餐","幽门螺杆菌呼气试验","腹部超声"],"answer":0,"explanation":"胃镜+黏膜活检是慢性胃炎确诊手段，可同时检测幽门螺杆菌。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1852","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"消化性溃疡的主要病因是？","options":["饮食不规律","幽门螺杆菌感染和胃酸分泌过多","精神因素","遗传"],"answer":1,"explanation":"消化性溃疡发病是胃酸、胃蛋白酶的侵袭与黏膜防御失衡，Hp感染和胃酸是主要因素。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1853","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"消化性溃疡最典型的表现是？","options":["恶心呕吐","慢性、周期性、节律性上腹痛","反酸嗳气","腹泻"],"answer":1,"explanation":"消化性溃疡特点：慢性病程、周期性发作、节律性疼痛（胃溃疡餐后痛，十二指肠溃疡空腹痛/夜间痛）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1854","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"十二指肠溃疡疼痛的特点是？","options":["餐后立即痛","空腹痛（餐后3-4小时）和夜间痛，进食后缓解","无规律","排便后缓解"],"answer":1,"explanation":"十二指肠溃疡疼痛-进食-缓解的节律；胃溃疡为进食-疼痛-缓解。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1855","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"消化性溃疡最常见的并发症是？","options":["出血","穿孔","幽门梗阻","癌变"],"answer":0,"explanation":"出血是消化性溃疡最常见并发症（十二指肠溃疡多见），表现为呕血或黑便。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1856","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"消化性溃疡穿孔的表现是？","options":["黑便","呕血","突发剧烈腹痛、腹膜刺激征、膈下游离气体","黄疸"],"answer":2,"explanation":"溃疡穿孔：突发刀割样腹痛、板状腹、膈下游离气体，需急诊手术。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1857","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胃溃疡癌变的警惕信号不包括？","options":["规律性疼痛加重","疼痛规律改变（失去节律）","消瘦、贫血","大便隐血持续阳性"],"answer":0,"explanation":"胃溃疡疼痛规律改变、消瘦、贫血、隐血持续阳性提示癌变；规律性疼痛加重表述不清，规律改变才是警示。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1858","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝硬化最常见的病因是？","options":["胆汁淤积","酒精性肝病","药物性肝损害","乙型病毒性肝炎"],"answer":3,"explanation":"我国肝硬化以乙肝后肝硬化最常见；欧美以酒精性为主。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1859","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝硬化门脉高压的表现不包括？","options":["腹水","脾大","黄疸进行性加深（必然）","侧支循环建立"],"answer":2,"explanation":"门脉高压表现：脾大、侧支循环、腹水；黄疸为肝功能减退表现，非门脉高压必然表现。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1860","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝硬化最严重的并发症是？","options":["上消化道出血","肝性脑病","感染","肝肾综合征"],"answer":1,"explanation":"肝性脑病是肝硬化最严重的并发症，也是主要死因之一。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1861","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝硬化食管胃底静脉曲张破裂出血的首选急救措施是？","options":["立即手术","口服止血药","内镜下止血（套扎/硬化）+药物（生长抑素）","输血观察"],"answer":2,"explanation":"食管胃底静脉曲张破裂出血：生长抑素（奥曲肽）+内镜下套扎/硬化剂治疗，必要时三腔二囊管。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1862","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝性脑病的常见诱因不包括？","options":["便秘","低蛋白饮食","感染","高蛋白饮食、感染、便秘、消化道出血"],"answer":3,"explanation":"高蛋白饮食（产氨增多）、感染、便秘、出血是肝性脑病常见诱因；低蛋白饮食是预防措施。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1863","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝性脑病最具特征性的体征是？","options":["黄疸","下肢水肿","腹水","扑翼样震颤"],"answer":3,"explanation":"扑翼样震颤是肝性脑病（前驱期、昏迷前期）的特征性体征。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1864","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肝性脑病饮食的原则是？","options":["高脂饮食","高蛋白饮食","禁食碳水化合物","限制蛋白质摄入（以植物蛋白为主）"],"answer":3,"explanation":"肝性脑病限制蛋白摄入、以植物蛋白为主，减少氨的来源。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1865","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"原发性肝癌最常见的病因是？","options":["血吸虫病","酒精","黄曲霉毒素（协同因素）","乙型肝炎病毒感染"],"answer":3,"explanation":"乙肝病毒感染是我国原发性肝癌最主要的病因（肝炎-肝硬化-肝癌三部曲）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1866","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"原发性肝癌的首选筛查方法是？","options":["CT","甲胎蛋白（AFP）+肝脏超声","MRI","肝穿刺活检"],"answer":1,"explanation":"AFP+超声是肝癌高危人群（乙肝、肝硬化）的首选筛查组合。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1867","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"原发性肝癌的确诊方法是？","options":["AFP升高","肝穿刺活检（病理）","超声","CT增强"],"answer":1,"explanation":"病理学检查（肝穿刺活检）是肝癌确诊的金标准；AFP>400μg/L结合影像可临床诊断。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1868","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性胰腺炎最常见的病因是？","options":["高脂血症","大量饮酒","暴饮暴食","胆道疾病（胆石症）"],"answer":3,"explanation":"胆石症是我国急性胰腺炎最常见的病因（胆源性胰腺炎）；饮酒是重要诱因。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1869","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性胰腺炎的主要表现是？","options":["腹泻","阵发性绞痛","转移性右下腹痛","持续性上腹痛向腰背部放射，弯腰抱膝可减轻"],"answer":3,"explanation":"急性胰腺炎：持续性上腹痛向腰背放射，恶心呕吐后腹痛不缓解（与胃病区别）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1870","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性胰腺炎治疗的基本原则是？","options":["大量进食","立即手术","禁食胃肠减压、抑制胰酶分泌、补液","抗生素为主"],"answer":2,"explanation":"急性胰腺炎以内科治疗为主：禁食胃肠减压、抑酸抑酶、液体复苏；胆源性或重症者手术。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1871","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"溃疡性结肠炎的典型表现是？","options":["脂肪泻","水样便无脓血","便秘","黏液脓血便伴腹痛、里急后重"],"answer":3,"explanation":"溃疡性结肠炎：腹泻（黏液脓血便）、腹痛（左下腹）、里急后重，反复发作。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1872","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"溃疡性结肠炎病变主要累及？","options":["直肠和乙状结肠（连续性病变）","回肠末端","全小肠","胃"],"answer":0,"explanation":"溃疡性结肠炎病变从直肠开始连续向上蔓延，黏膜弥漫性炎症。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1873","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"克罗恩病的病变特点是？","options":["仅累及直肠","连续性病变","全消化道节段性（跳跃性）病变，好发回肠末端","仅累及结肠"],"answer":2,"explanation":"克罗恩病：节段性（跳跃性）全消化道病变，好发回肠末端和回盲部，可形成瘘管。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1874","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性肾小球肾炎的主要表现是？","options":["大量白细胞尿","蛋白尿、血尿、高血压、水肿","尿频尿急尿痛","肾绞痛"],"answer":1,"explanation":"慢性肾炎基本表现：蛋白尿、血尿、高血压、水肿，缓慢进展为肾衰。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1875","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肾病综合征的诊断标准是？","options":["大量蛋白尿（>3.5g/24h）+低白蛋白血症（<30g/L）","血尿+蛋白尿","高血压+水肿","氮质血症+贫血"],"answer":0,"explanation":"肾病综合征两要素：大量蛋白尿（>3.5g/24h）和低白蛋白血症（<30g/L），水肿和高脂血症为继发。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1876","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肾病综合征最常见的并发症是？","options":["蛋白质营养不良","血栓","急性肾损伤","感染"],"answer":3,"explanation":"感染是肾病综合征最常见并发症（大量免疫球蛋白丢失），血栓栓塞为其严重并发症。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1877","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性肾小球肾炎（链球菌感染后）的前驱期一般为？","options":["感染后1个月以上","感染后1-2天","感染后1-3周","感染同时"],"answer":2,"explanation":"链球菌感染后1-3周出现血尿、蛋白尿、水肿、高血压（急性肾炎综合征）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1878","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性肾盂肾炎的典型表现是？","options":["下肢水肿","无痛性血尿","大量蛋白尿","发热、腰痛、膀胱刺激征"],"answer":3,"explanation":"急性肾盂肾炎：发热寒战、腰痛（肾区叩痛）、尿频尿急尿痛。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1879","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性肾衰竭最常见的病因是？","options":["慢性肾小球肾炎","糖尿病肾病","高血压肾病","多囊肾"],"answer":0,"explanation":"我国慢性肾衰以慢性肾小球肾炎为最常见病因（糖尿病肾病上升趋势）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1880","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性肾衰竭患者饮食的原则是？","options":["高磷饮食","高蛋白饮食","低磷高钾饮食","优质低蛋白饮食"],"answer":3,"explanation":"慢性肾衰优质低蛋白饮食，减少氮质潴留；限磷，避免高钾食物。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1881","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"尿毒症最早出现的症状是？","options":["抽搐","皮肤瘙痒","心力衰竭","消化系统症状（食欲不振、恶心）"],"answer":3,"explanation":"尿毒症毒素刺激胃肠道，食欲不振、恶心是最早、最常见的症状。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1882","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"尿毒症贫血的主要原因是？","options":["促红细胞生成素减少","铁摄入不足（唯一）","溶血","失血"],"answer":0,"explanation":"肾脏产生促红细胞生成素减少是尿毒症贫血的主要原因，用EPO治疗。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1883","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"缺铁性贫血最常见的病因是？","options":["铁吸收障碍","铁摄入不足（成人）","慢性失血（女性月经过多、消化道慢性失血）","溶血"],"answer":2,"explanation":"成人缺铁性贫血以慢性失血最常见；婴幼儿以铁摄入不足为主。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1884","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"缺铁性贫血的典型血象是？","options":["大细胞性贫血","小细胞低色素性贫血","正细胞性贫血","白细胞减少"],"answer":1,"explanation":"缺铁性贫血：红细胞小、中心淡染区扩大（小细胞低色素），MCV、MCH、MCHC均降低。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1885","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"缺铁性贫血确诊的检查是？","options":["血常规","血清铁降低（单项）","血清铁蛋白降低","骨髓穿刺"],"answer":2,"explanation":"血清铁蛋白是反映储存铁最敏感指标，降低可确诊缺铁。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1886","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"口服铁剂治疗缺铁性贫血，网织红细胞开始升高的时间是？","options":["服药后3-4天","服药后1小时","服药后1周","服药后1个月"],"answer":0,"explanation":"铁剂治疗后3-4天网织红细胞开始升高，7-10天达高峰。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1887","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"巨幼细胞贫血的病因是？","options":["再生障碍","缺铁","溶血","叶酸和（或）维生素B12缺乏"],"answer":3,"explanation":"叶酸或B12缺乏致DNA合成障碍，红细胞大（大细胞性），骨髓巨幼变。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1888","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"再生障碍性贫血的主要表现是？","options":["贫血、出血、感染（全血细胞减少）","单纯贫血","脾大","黄疸"],"answer":0,"explanation":"再障三系减少：贫血、出血（血小板少）、感染（白细胞少），肝脾一般不大。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1889","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"再生障碍性贫血确诊的检查是？","options":["铁蛋白","血常规","网织红细胞","骨髓穿刺（增生低下）"],"answer":3,"explanation":"再障骨髓象：多部位增生减低或重度减低，非造血细胞增多。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1890","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性白血病的主要表现是？","options":["贫血、出血、感染、浸润（肝脾淋巴结肿大）","单纯乏力","黄疸","腹水"],"answer":0,"explanation":"急性白血病四联：贫血、出血、感染、白血病细胞浸润（骨痛、肝脾淋巴结肿大）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1891","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性白血病确诊的依据是？","options":["骨髓象（原始细胞≥20%）","血常规","淋巴结活检","免疫学检查"],"answer":0,"explanation":"骨髓原始细胞≥20%是急性白血病的确诊标准（WHO标准）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1892","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性白血病化疗后最严重的并发症是？","options":["恶心呕吐","脱发","骨髓抑制（感染、出血）","口腔溃疡"],"answer":2,"explanation":"化疗后骨髓抑制期（7-14天）感染和出血风险最高，需保护隔离。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1893","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"特发性血小板减少性紫癜（ITP）的主要表现是？","options":["脾大明显","关节肿痛","皮肤黏膜出血（瘀点、紫癜）","溶血"],"answer":2,"explanation":"ITP以皮肤黏膜出血为主，血小板减少、骨髓巨核细胞成熟障碍。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1894","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲状腺功能亢进症最常见的原因是？","options":["结节性甲状腺肿","弥漫性毒性甲状腺肿（Graves病）","甲状腺癌","亚急性甲状腺炎"],"answer":1,"explanation":"Graves病是甲亢最常见病因，表现为高代谢症候群、甲状腺肿大、眼征。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1895","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲亢的典型表现不包括？","options":["甲状腺肿大","心悸、多汗、消瘦","体重增加","眼征（突眼）"],"answer":2,"explanation":"甲亢代谢亢进：心悸、多汗、食欲亢进但消瘦、手抖、突眼；体重增加不是甲亢表现。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1896","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲亢诊断最敏感的指标是？","options":["T4","T3","血清TSH（促甲状腺激素）","甲状腺摄碘率"],"answer":2,"explanation":"TSH是最敏感的筛查指标（甲亢时降低）；FT3、FT4升高确诊。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1897","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲亢治疗的首选方法（成人初治）是？","options":["抗甲状腺药物（甲巯咪唑）","立即手术","碘131治疗","甲状腺素替代"],"answer":0,"explanation":"成人初治甲亢首选抗甲状腺药物（甲巯咪唑、丙硫氧嘧啶），疗程1.5-2年。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1898","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲亢危象的诱因不包括？","options":["精神刺激","感染、手术、创伤","放射性碘治疗后","受凉感冒（轻度）"],"answer":3,"explanation":"甲亢危象诱因：感染、手术、创伤、精神刺激、碘治疗早期等应激状态；轻度受凉一般不诱发。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1899","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲亢危象的表现是？","options":["嗜睡、体重增加","低热、心率慢","高热、大汗、心动过速（>140次/分）、烦躁、呕吐腹泻","血压升高、便秘"],"answer":2,"explanation":"甲亢危象：高热大汗、心率显著增快、烦躁谵妄、呕吐腹泻，死亡率高，需紧急处理。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1900","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲状腺功能减退症的主要表现是？","options":["消瘦","心悸、多汗","代谢减慢（怕冷、乏力、水肿、体重增加）","突眼"],"answer":2,"explanation":"甲减：怕冷、乏力、嗜睡、黏液性水肿、体重增加、心率慢、便秘。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1901","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"甲减最严重的并发症是？","options":["心包积液","黏液性水肿昏迷","贫血","高脂血症"],"answer":1,"explanation":"黏液性水肿昏迷是甲减最严重的并发症，表现为低体温、心动过缓、意识障碍。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1902","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病最常见的类型是？","options":["1型糖尿病","2型糖尿病","妊娠糖尿病","特殊类型糖尿病"],"answer":1,"explanation":"2型糖尿病占90%以上，多见于成人，与胰岛素抵抗和分泌不足有关。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1903","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病的典型症状是？","options":["多饮、多食、多尿、体重减轻（三多一少）","多汗、心悸","水肿、少尿","便秘、腹胀"],"answer":0,"explanation":"糖尿病典型三多一少：多尿、多饮、多食、体重减轻。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1904","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病最基本的治疗措施是？","options":["饮食治疗和运动","口服降糖药","胰岛素","血糖监测"],"answer":0,"explanation":"饮食治疗是糖尿病一切治疗的基础，终身坚持。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1905","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"1型糖尿病的治疗必须使用？","options":["胰岛素","口服降糖药","饮食控制即可","运动疗法"],"answer":0,"explanation":"1型糖尿病胰岛β细胞破坏、胰岛素绝对缺乏，必须胰岛素治疗。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1906","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病最常见的急性并发症是？","options":["高渗性昏迷","低血糖昏迷","糖尿病酮症酸中毒","乳酸性酸中毒"],"answer":2,"explanation":"酮症酸中毒（DKA）是糖尿病最常见的急性并发症，诱因为感染、胰岛素中断等。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1907","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病酮症酸中毒的特征表现是？","options":["便秘","低热","呼吸深大（Kussmaul呼吸）、烂苹果味、脱水","黄疸"],"answer":2,"explanation":"DKA：脱水、深大呼吸、烂苹果味、恶心呕吐、意识障碍，血糖高、酮体阳性。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1908","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病酮症酸中毒治疗的关键是？","options":["补液（首要）+小剂量胰岛素","立即补钾","立即纠酸","立即降糖至正常"],"answer":0,"explanation":"DKA治疗首要措施是补液（恢复血容量），同时小剂量胰岛素持续静滴。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1909","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病微血管病变最特征性的表现是？","options":["糖尿病肾病和糖尿病视网膜病变","冠心病","脑梗死","下肢动脉硬化"],"answer":0,"explanation":"微血管病变特征：糖尿病肾病、视网膜病变、神经病变；大血管病变为冠心病、脑卒中等。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1910","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病肾病最早期的表现是？","options":["大量蛋白尿","微量白蛋白尿","血肌酐升高","水肿"],"answer":1,"explanation":"糖尿病肾病早期表现为微量白蛋白尿，定期筛查尿微量白蛋白/肌酐比值。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1911","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"糖尿病足的主要预防措施是？","options":["控制血糖+足部护理（避免破损感染）","截肢","热敷","穿紧鞋"],"answer":0,"explanation":"糖尿病足预防：控制血糖、每日检查足部、避免破损、穿宽松鞋袜、及时处理胼胝。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1912","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低血糖的诊断标准（糖尿病患者接受降糖治疗时）是？","options":["血糖≤3.9 mmol/L","血糖≤2.8 mmol/L","血糖≤5.0 mmol/L","血糖≤6.1 mmol/L"],"answer":0,"explanation":"接受药物治疗糖尿病患者血糖≤3.9mmol/L即为低血糖，需立即处理。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1913","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低血糖昏迷的紧急处理是？","options":["立即静脉注射50%葡萄糖","立即注射胰岛素","口服降糖药","大量饮水"],"answer":0,"explanation":"低血糖昏迷立即静注50%葡萄糖40-60ml，清醒后继续进食。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1914","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"类风湿关节炎的基本病理改变是？","options":["骨质增生","血管炎","滑膜炎","软骨退变"],"answer":2,"explanation":"类风湿关节炎基本病理为滑膜炎，滑膜增生形成血管翳，侵蚀软骨骨质。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1915","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"类风湿关节炎的典型关节表现是？","options":["游走性大关节痛","单侧大关节肿痛","对称性小关节（近端指间、掌指、腕）晨僵","无痛性关节畸形"],"answer":2,"explanation":"RA：对称性多关节炎（腕、掌指、近端指间），晨僵>1小时，晚期关节畸形。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1916","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"类风湿关节炎的诊断性抗体是？","options":["类风湿因子（RF）和抗CCP抗体","抗核抗体","抗dsDNA抗体","抗-HBs"],"answer":0,"explanation":"RF和抗CCP抗体是RA的诊断性抗体，抗CCP特异性更高。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1917","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"系统性红斑狼疮最常累及的器官是？","options":["肺","心脏","肾脏（狼疮性肾炎）","神经系统"],"answer":2,"explanation":"SLE最常累及肾脏（狼疮性肾炎），是主要死因之一。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1918","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"系统性红斑狼疮的特征性表现是？","options":["关节痛","面部蝶形红斑","脱发","口腔溃疡"],"answer":1,"explanation":"面部蝶形红斑是SLE的特征性皮疹，具有诊断意义。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1919","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"系统性红斑狼疮治疗的基础药物是？","options":["羟氯喹（联合糖皮质激素）","抗生素","免疫球蛋白","环磷酰胺（重症）"],"answer":0,"explanation":"羟氯喹是SLE的基础用药，可减少复发和激素用量；重症用环磷酰胺冲击。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1920","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"有机磷农药中毒的主要机制是？","options":["麻痹呼吸中枢","抑制细胞色素氧化酶","阻断神经肌肉接头","抑制胆碱酯酶，乙酰胆碱蓄积"],"answer":3,"explanation":"有机磷抑制胆碱酯酶，乙酰胆碱蓄积产生毒蕈碱样（M）和烟碱样（N）症状。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1921","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"有机磷中毒毒蕈碱样症状的表现是？","options":["瞳孔散大","肌束震颤","瞳孔缩小、流涎、多汗、支气管分泌物增多","皮肤干燥"],"answer":2,"explanation":"M样症状：瞳孔缩小、腺体分泌增多（流涎、多汗、肺水肿）、平滑肌痉挛。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1922","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"有机磷中毒烟碱样症状的表现是？","options":["支气管痉挛","瞳孔缩小","流涎","肌束震颤、肌肉痉挛"],"answer":3,"explanation":"N样症状：肌束震颤、肌肉痉挛、无力；M样症状为腺体分泌和平滑肌痉挛。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1923","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"有机磷中毒的特效解毒药是？","options":["阿托品+氯解磷定","纳洛酮","美蓝","亚硝酸钠"],"answer":0,"explanation":"阿托品对抗M样症状，氯解磷定恢复胆碱酯酶活性（对抗N样症状），两药合用。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1924","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阿托品化的表现不包括？","options":["瞳孔较前扩大","瞳孔缩小","口干、皮肤干燥","肺部啰音减少"],"answer":1,"explanation":"阿托品化：瞳孔扩大、口干、皮肤干燥、心率增快、肺部啰音减少；瞳孔缩小提示未达阿托品化或中毒加深。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1925","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"一氧化碳中毒最敏感的组织是？","options":["肾脏","肝脏","脑和心脏","皮肤"],"answer":2,"explanation":"脑和心肌对缺氧最敏感，CO中毒以神经系统损害为主。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1926","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"一氧化碳中毒迟发性脑病的发生时间是？","options":["中毒后立即","中毒当时","清醒后1年","清醒后2-60天"],"answer":3,"explanation":"部分CO中毒患者清醒后2-60天出现痴呆、精神症状、帕金森表现等迟发性脑病。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1927","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中暑高热（热射病）的首要处理是？","options":["应用退热药","补液","吸氧","迅速降温（物理降温为主）"],"answer":3,"explanation":"热射病死亡率高，首要措施是迅速降温（体外+体内降温），同时补液、护器官。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1928","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"淹溺患者救出后首要处理是？","options":["注射呼吸兴奋剂","控水","保暖","清理呼吸道、心肺复苏"],"answer":3,"explanation":"淹溺急救：立即清理口鼻异物、心肺复苏（CPR），不主张长时间控水耽误复苏。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1929","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"电击伤现场急救的首要措施是？","options":["心肺复苏","迅速脱离电源","包扎伤口","注射破伤风抗毒素"],"answer":1,"explanation":"电击伤急救：先断电（用绝缘物挑开电线），再评估呼吸心跳并行CPR。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1930","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"细菌性食物中毒的特点是？","options":["集体发病、潜伏期短、以胃肠道症状为主","散发、潜伏期长","以神经系统症状为主","不发热"],"answer":0,"explanation":"细菌性食物中毒：进食同一食物后短期内集体发病，恶心呕吐腹泻为主。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1931","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"沙门菌食物中毒的潜伏期一般为？","options":["1周","1小时","3天","4-24小时（多在12-24小时）"],"answer":3,"explanation":"沙门菌食物中毒潜伏期4-24小时，表现为发热、恶心呕吐、腹泻。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1932","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"河豚毒素中毒的主要表现是？","options":["皮疹","剧烈呕吐","腹泻","口唇麻木、四肢无力（神经麻痹）"],"answer":3,"explanation":"河豚毒素阻断钠通道，口唇舌尖麻木、四肢无力、呼吸麻痹，无特效解毒药。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1933","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"亚硝酸盐中毒的机制是？","options":["抑制胆碱酯酶","使血红蛋白氧化为高铁血红蛋白，失去携氧能力","麻痹呼吸中枢","破坏红细胞膜"],"answer":1,"explanation":"亚硝酸盐氧化血红蛋白为高铁血红蛋白，皮肤黏膜发绀，用亚甲蓝解救。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1934","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性上呼吸道感染最常见的病原体是？","options":["真菌","细菌","支原体","病毒"],"answer":3,"explanation":"普通感冒90%以上由病毒引起（鼻病毒、冠状病毒等），不需常规抗生素。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1935","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性扁桃体炎最常见的病原体是？","options":["溶血性链球菌","病毒","支原体","真菌"],"answer":0,"explanation":"急性扁桃体炎以溶血性链球菌常见，需足量青霉素类抗生素治疗。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1936","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性支气管炎的诊断标准是？","options":["咳嗽1个月","咳嗽咳痰每年3个月、连续2年以上","咳嗽2年、每年1个月","咳血1年"],"answer":1,"explanation":"慢支诊断：咳嗽咳痰每年持续3个月、连续2年或以上，并排除其他心肺疾病。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1937","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"慢性支气管炎急性发作的首要治疗是？","options":["镇咳","控制感染","祛痰","平喘"],"answer":1,"explanation":"慢支急性发作多由感染诱发，控制感染是首要治疗。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1938","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺心病的最主要病因是？","options":["冠心病","风湿性心脏病","慢性阻塞性肺疾病","心肌病"],"answer":2,"explanation":"COPD是慢性肺源性心脏病最主要的病因（缺氧致肺动脉高压）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-1939","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"肺心病急性加重期的首要治疗是？","options":["扩血管","强心","利尿","控制感染、改善呼吸功能"],"answer":3,"explanation":"肺心病加重期以控制感染、保持呼吸道通畅、纠正缺氧为首要，慎用利尿强心。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-1940","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"无菌术的原则不包括？","options":["手术人员可佩戴有菌手套操作","手术区消毒铺巾","器械物品灭菌","操作规程严格"],"answer":0,"explanation":"无菌术要求手术人员洗手穿无菌衣、戴无菌手套，不能带菌操作。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1941","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"手术区皮肤消毒的范围应包括切口周围？","options":["50cm","5cm","30cm","至少15cm"],"answer":3,"explanation":"手术区消毒范围至少包括切口周围15cm，如有延长切口的可能应扩大消毒范围。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1942","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"外科洗手后，双手应保持的姿势是？","options":["随意放置","自然下垂","交叉放于背后","拱手置于胸前"],"answer":3,"explanation":"洗手后双手拱于胸前，不再接触有菌物品，避免污染。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1943","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"手术切口感染最常见的病原菌是？","options":["大肠埃希菌","金黄色葡萄球菌","厌氧菌","铜绿假单胞菌"],"answer":1,"explanation":"手术切口感染以金黄色葡萄球菌最常见（皮肤常驻菌）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1944","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"等渗性缺水的特点是？","options":["失水多于失钠","水和钠成比例丢失，血钠正常","失钠多于失水","血钠<130mmol/L"],"answer":1,"explanation":"等渗性缺水（急性缺水）水钠等比例丢失，血钠135-145mmol/L正常，外科最常见。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1945","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高渗性缺水的特点是？","options":["失水多于失钠，血钠>145mmol/L","水钠等比例丢失","血钠<130mmol/L","尿量增多"],"answer":0,"explanation":"高渗性缺水（原发性缺水）失水多于失钠，口渴明显、尿少、比重高。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1946","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低渗性缺水的特点是？","options":["尿比重增高","口渴明显","血钠>150mmol/L","失钠多于失水，血钠<135mmol/L"],"answer":3,"explanation":"低渗性缺水失钠多于失水，早期无口渴、尿少晚期明显、易休克。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1947","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低钾血症的心电图典型表现是？","options":["QRS增宽","T波高尖","T波低平、U波增高","P波消失"],"answer":2,"explanation":"低钾血症心电图：T波低平或倒置、U波出现或增高、ST段下移。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1948","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"高钾血症的心电图典型表现是？","options":["P-R间期缩短","U波增高","T波低平","T波高尖"],"answer":3,"explanation":"高钾血症心电图：T波高尖、Q-T间期延长，重者QRS增宽、室颤。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1949","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"补钾的原则不包括？","options":["见尿补钾（尿量>40ml/h）","浓度不超过0.3%","可直接静脉推注","速度不宜过快"],"answer":2,"explanation":"补钾禁止静脉推注，浓度<0.3%、速度<0.75g/h、见尿补钾、每日总量<6-8g。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1950","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"代谢性酸中毒的典型表现是？","options":["呼吸正常","呼吸浅慢","呼吸深大（Kussmaul呼吸）","发绀"],"answer":2,"explanation":"代谢性酸中毒呼吸代偿性深大（酸中毒大呼吸），呼出CO2增多。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1951","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"代谢性碱中毒的常见原因是？","options":["休克","腹泻","大量呕吐（胃酸丢失）","肾功能不全"],"answer":2,"explanation":"大量呕吐丢失胃酸（H+、Cl-）致代谢性碱中毒，伴低钾低氯。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1952","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"休克的基本病理生理改变是？","options":["心输出量增加","血容量增加","有效循环血量减少、微循环障碍","血管扩张（所有类型）"],"answer":2,"explanation":"休克本质是有效循环血量锐减和组织灌注不足，微循环障碍是共同环节。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1953","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"休克早期（代偿期）的表现是？","options":["精神紧张、面色苍白、脉压缩小","血压明显下降","意识丧失","无尿"],"answer":0,"explanation":"休克早期血压可正常，表现为烦躁、面色苍白、心率增快、脉压缩小（<30mmHg）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1954","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"休克监测中最简单有效的指标是？","options":["血气","中心静脉压","尿量","乳酸"],"answer":2,"explanation":"尿量反映肾脏灌注，是休克监测最简单有效的指标（<25ml/h提示灌注不足）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1955","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"休克患者补液的首要原则是？","options":["先纠酸","快速补充血容量","先强心","先利尿"],"answer":1,"explanation":"休克治疗首要措施是补充血容量（先晶体后胶体），恢复有效循环。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1956","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"中心静脉压（CVP）正常值为？","options":["15-20 cmH₂O","0-5 cmH₂O","5-12 cmH₂O","20-30 cmH₂O"],"answer":2,"explanation":"CVP正常5-12cmH₂O；低血压+低CVP提示血容量不足，需快速补液。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1957","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"低血容量休克补充血容量首选的液体是？","options":["全血","平衡盐溶液（晶体液）","白蛋白","右旋糖酐"],"answer":1,"explanation":"休克补液先晶体（平衡盐溶液）后胶体，晶体液可快速恢复血容量。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1958","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"感染性休克（脓毒性休克）的治疗关键是？","options":["仅补液","控制感染+液体复苏","仅用升压药","仅用激素"],"answer":1,"explanation":"感染性休克需同时控制感染（抗生素、引流）和液体复苏，必要时血管活性药。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1959","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"失血性休克输血的指征是？","options":["任何失血","失血量超过血容量的20-30%（Hb<70g/L）","失血<10%","仅慢性贫血"],"answer":1,"explanation":"失血>20-30%或Hb<70g/L需输血；轻度失血用晶体液补充即可。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1960","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"休克指数（脉搏/收缩压）为1.0提示？","options":["无失血","失血<10%","失血>50%","失血约20-30%"],"answer":3,"explanation":"休克指数=脉率/收缩压：0.5正常，1.0提示失血20-30%，1.5提示失血30-50%。","exam":"医疗编","__sub":"外科临床","diff":3,"id":"yl-1961","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"麻醉前用药的目的不包括？","options":["镇静、镇痛","增加麻醉药用量","抑制腺体分泌","预防不良反应"],"answer":1,"explanation":"麻醉前用药为镇静、镇痛、抑制分泌、预防不良反应，不增加麻醉药用量。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1962","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"全身麻醉最重要的环节是？","options":["维持呼吸道通畅、保证氧供","监测血压","补液","体位"],"answer":0,"explanation":"全麻管理核心是气道管理和呼吸支持，防止缺氧和CO2蓄积。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1963","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"气管内插管的主要目的是？","options":["减少麻醉药用量","保持呼吸道通畅、便于控制呼吸","便于手术操作","防止误吸（唯一目的）"],"answer":1,"explanation":"气管插管保持气道通畅、便于机械通气和防止误吸，是全麻重要保障。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1964","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"局部麻醉药中毒的早期表现是？","options":["口周麻木、头晕、耳鸣","昏迷","抽搐（晚期）","呼吸停止（晚期）"],"answer":0,"explanation":"局麻药中毒早期：口周麻木、头晕、耳鸣、言语不清，重者抽搐、惊厥。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1965","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"局麻药中加入肾上腺素的目的是？","options":["止痛","增强麻醉效果（直接）","预防过敏","延缓吸收、延长作用时间、减少中毒"],"answer":3,"explanation":"肾上腺素收缩局部血管，延缓局麻药吸收，延长作用、减少全身中毒。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1966","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腰麻（蛛网膜下腔阻滞）最常见的并发症是？","options":["尿潴留","头痛","低血压（交感神经阻滞）","感染"],"answer":2,"explanation":"腰麻阻滞交感神经致血管扩张、血压下降，是最常见并发症。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1967","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腰麻后头痛的特点是？","options":["持续一周以上","平卧加重","与体位无关","坐起或站立时加重、平卧减轻"],"answer":3,"explanation":"腰麻后头痛为低颅压性头痛，坐起加重、平卧缓解，多在一周内自愈。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1968","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"硬膜外麻醉最严重的并发症是？","options":["低血压","全脊髓麻醉","尿潴留","感染"],"answer":1,"explanation":"硬膜外导管误入蛛网膜下腔致全脊髓麻醉（呼吸停止、意识丧失），最严重。","exam":"医疗编","__sub":"外科临床","diff":3,"id":"yl-1969","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"创伤急救的基本原则是？","options":["先搬运","先处理骨折","先包扎","先救命后治伤（先处理危及生命的问题）"],"answer":3,"explanation":"创伤急救优先处理危及生命的问题（气道、呼吸、循环），再处理其他损伤。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1970","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"现场心肺复苏的步骤顺序是？","options":["胸外按压→开放气道→人工呼吸（C-A-B）","A-B-C","开放气道→按压→呼吸","人工呼吸→按压"],"answer":0,"explanation":"现行指南强调先胸外按压（C），再开放气道（A）、人工呼吸（B）。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1971","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胸外按压的部位是？","options":["心尖部","胸骨中下1/3交界处（两乳头连线中点）","胸骨上段","左胸部"],"answer":1,"explanation":"按压部位为胸骨中下段（两乳头连线中点），深度5-6cm，频率100-120次/分。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1972","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"单人心肺复苏时按压与人工呼吸的比例是？","options":["30:2","15:2","5:1","10:1"],"answer":0,"explanation":"单人或双人施救成人CPR按压与通气比均为30:2。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1973","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"止血带止血的注意事项不包括？","options":["每小时放松1-2分钟","连续使用不超过1小时（可延长至2小时）","记录上止血带时间","上臂中1/3禁用（桡神经）"],"answer":1,"explanation":"止血带连续使用一般不超过1小时，最长不超过2-3小时（每小时放松1-2分钟）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1974","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"烧伤面积计算（中国九分法）中，头颈部占？","options":["18%","6%","12%","9%"],"answer":3,"explanation":"九分法：头颈9%（发部3、面部3、颈部3）、双上肢18%、躯干27%、双下肢46%。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1975","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"烧伤面积计算中，双上肢占？","options":["46%","9%","27%","18%"],"answer":3,"explanation":"双上肢18%（双手5、双前臂6、双上臂7）。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1976","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"烧伤面积计算中，双下肢（含臀部）占？","options":["27%","36%","46%","54%"],"answer":2,"explanation":"双下肢46%（含臀部5%），成年男性；女性双足双臀各多1%。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1977","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"烧伤深度判断中，浅Ⅱ度烧伤的特点是？","options":["无水疱、干燥","水疱、剧痛、创面红润（真皮浅层）","焦痂形成","痛觉消失"],"answer":1,"explanation":"浅Ⅱ度伤及真皮浅层，水疱大、剧痛、创面红肿，1-2周愈合不留瘢痕。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1978","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"深Ⅱ度烧伤的特点是？","options":["焦痂、无痛","剧痛、水疱大","痛觉迟钝、创面红白相间（真皮深层）","仅红斑"],"answer":2,"explanation":"深Ⅱ度伤及真皮深层，痛觉迟钝、水疱小、创面红白相间，3-4周愈合多留瘢痕。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1979","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"Ⅲ度烧伤的特点是？","options":["焦痂、蜡白或炭化、痛觉消失","水疱、剧痛","红斑、灼痛","水疱小、痛觉迟钝"],"answer":0,"explanation":"Ⅲ度伤及皮肤全层甚至皮下，创面蜡白/焦黄/炭化、干燥无水疱、痛觉消失，需手术植皮。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1980","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"烧伤休克补液计算中，第一个24小时补液量（成人）为？","options":["固定3000ml","烧伤面积×体重×0.5ml","烧伤面积×体重×3ml","烧伤面积%×体重kg×1.5ml+基础需要量2000ml"],"answer":3,"explanation":"第一个24小时补液：每1%面积每公斤体重1.5ml（胶体+晶体）+基础水分2000ml。","exam":"医疗编","__sub":"外科临床","diff":3,"id":"yl-1981","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"烧伤创面处理的原则不包括？","options":["浅度创面防止感染","深度烧伤尽早切痂植皮","创面清洁","深度创面长期保守换药（必然）"],"answer":1,"explanation":"深Ⅱ度和Ⅲ度烧伤应尽早切（削）痂植皮，不宜长期保守换药。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1982","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"冻伤的急救措施是？","options":["用力揉搓","用38-42℃温水复温","火烤","雪搓"],"answer":1,"explanation":"冻伤用温水（38-42℃）快速复温，禁用火烤、雪搓、用力揉搓。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1983","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"毒蛇咬伤的急救措施是？","options":["热敷","立即切开伤口大范围切除","近心端绑扎、清创排毒、注射抗蛇毒血清","饮酒"],"answer":2,"explanation":"毒蛇咬伤：肢体近心端绑扎（每15-20分钟放松1-2分钟）、伤口冲洗、抗蛇毒血清。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1984","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风的预防措施不包括？","options":["彻底清创","伤口深部缝合包扎（厌氧环境）","注射破伤风抗毒素（TAT）","接种破伤风类毒素"],"answer":1,"explanation":"破伤风梭菌为厌氧菌，深部缝合包扎造成厌氧环境利于繁殖，应敞开伤口。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1985","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风发作的典型表现是？","options":["感觉减退","弛缓性瘫痪","牙关紧闭、苦笑面容、角弓反张","意识丧失（早期）"],"answer":2,"explanation":"破伤风典型：牙关紧闭、苦笑面容、颈项强直、角弓反张（骨骼肌强直性痉挛），神志清楚。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1986","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"破伤风患者病室环境的要求是？","options":["强光照射","避光、安静、减少刺激","嘈杂环境","频繁探视"],"answer":1,"explanation":"破伤风痉挛可因声光刺激诱发，病室应避光、安静、减少刺激。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1987","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"气性坏疽的病原体是？","options":["大肠埃希菌","破伤风梭菌","金黄色葡萄球菌","产气荚膜梭菌"],"answer":3,"explanation":"气性坏疽由产气荚膜梭菌等厌氧菌引起，组织气肿、坏死、恶臭。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1988","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"气性坏疽的处理原则是？","options":["截肢（唯一方法）","保守换药","紧急手术切开减压、切除坏死组织、大剂量抗生素","热敷"],"answer":2,"explanation":"气性坏疽需紧急手术（切开引流、切除坏死组织、敞开伤口）+大剂量青霉素。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1989","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性阑尾炎最重要的病因是？","options":["饮食不当","阑尾腔梗阻（粪石等）+细菌感染","遗传","免疫因素"],"answer":1,"explanation":"阑尾腔梗阻后细菌繁殖、腔内压力升高，是急性阑尾炎的主要发病机制。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1990","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性阑尾炎腹痛的特点是？","options":["持续性左上腹痛","转移性右下腹痛","阵发性绞痛无固定点","全腹痛"],"answer":1,"explanation":"70-80%患者有转移性右下腹痛：先上腹或脐周，数小时后转移固定于右下腹。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1991","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性阑尾炎穿孔后弥漫性腹膜炎最主要的体征是？","options":["肠鸣音亢进","仅麦氏点压痛","全腹压痛、反跳痛及肌紧张","移动性浊音阳性"],"answer":2,"explanation":"阑尾穿孔后炎症扩散至全腹，出现全腹压痛、反跳痛和肌紧张等腹膜刺激征。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1992","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"急性阑尾炎出现腹肌紧张、反跳痛提示？","options":["单纯性阑尾炎","阑尾穿孔（腹膜炎）","慢性阑尾炎","阑尾周围脓肿（早期）"],"answer":1,"explanation":"腹膜刺激征（肌紧张、反跳痛）提示阑尾穿孔并发急性腹膜炎。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1993","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"阑尾周围脓肿的处理原则是？","options":["观察","立即手术切除阑尾","立即引流+切除","先抗感染、脓肿局限后择期手术（3个月后）"],"answer":3,"explanation":"阑尾周围脓肿先行抗感染+穿刺引流，炎症消退3个月后择期切除阑尾。","exam":"医疗编","__sub":"外科临床","diff":3,"id":"yl-1994","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹外疝最常见的类型是？","options":["腹股沟斜疝","腹股沟直疝","股疝","脐疝"],"answer":0,"explanation":"腹股沟斜疝最常见（占腹股沟疝的85-95%），多见于儿童和青壮年。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1995","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹股沟斜疝与直疝的鉴别要点是？","options":["斜疝经内环突出、可进入阴囊；直疝经直疝三角突出、不进阴囊","斜疝多见于老年人","直疝可进入阴囊","无区别"],"answer":0,"explanation":"斜疝经内环、腹股沟管进入阴囊（儿童青壮年多见）；直疝经直疝三角突出、不进阴囊（老年人多见）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1996","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹外疝发生嵌顿的紧急处理是？","options":["及时手法复位或急诊手术","观察等待","热敷","口服止痛药"],"answer":0,"explanation":"嵌顿疝超过3-4小时或手法复位失败，需急诊手术防止肠坏死。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1997","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"腹股沟疝术后应避免？","options":["咳嗽时按压伤口","早期下床活动（根据术式）","3个月内重体力劳动","保持大便通畅"],"answer":2,"explanation":"疝修补术后3个月内避免重体力劳动和剧烈运动，防止复发。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-1998","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胆石症按部位分为？","options":["大结石、小结石","胆固醇结石、胆色素结石","单发结石、多发结石","胆囊结石、肝外胆管结石、肝内胆管结石"],"answer":3,"explanation":"胆石按部位分：胆囊结石、肝外胆管结石、肝内胆管结石；按成分分胆固醇、胆色素、混合性。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-1999","_shard":"qk-yiliao-03"},{"module":"yiliao","prompt":"胆囊结石的典型表现是？","options":["无痛性黄疸","持续性钝痛","进食油腻后右上腹阵发性绞痛（胆绞痛）","腹泻"],"answer":2,"explanation":"胆囊结石典型为胆绞痛：进食油腻后右上腹阵发性绞痛，向右肩背放射。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2000","_shard":"qk-yiliao-03"}]);